INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (149, 'Amplifikasi Informasi Kebijakan Keuangan Negara melalui Sosial Media KPPN', 'Berdasarkan informasi kebijakan keuangan negara yang diamplifikasi dari media publikasi resmi milik Kemenkeu dan/atau DJPb', 6, 39, NULL, 0, 'Amplifikasi Informasi Kebijakan Keuangan Negara melalui Sosial Media KPPN', NULL, NULL, NULL, 'Screen shoot penerusan informasi pada media social KPPN', 'PMK Nomor 110/PMK.01/2022 tentang Pedoman Layanan Informasi Publik Pejabat Pengelola Informasi dan Dokumentasi di Lingkungan Kementerian Keuangan', NULL, NULL, NULL, '1. Meningkatkan engagement dan literasi fiskal publik secara menarik dan interaktif.
2. Mendukung keseragaman pesan dan memperkuat citra institusi perbendaharaan', 4, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (140, 'Kepatuhan Penggunaan User SPAN/SAKTI KPPN selaku BUN', 'Penilaian dilakukan berdasarkan kesesuaian penerbitan Berita Acara Peminjaman User SPAN/SAKTI bagi pejabat/pegawai yang berhalangan (Plh/cuti).', 5, 33, NULL, 0, 'Kepatuhan Penggunaan User SPAN/SAKTI KPPN selaku BUN', NULL, NULL, NULL, 'Berita Acara Peminjaman User SPAN dan/atau SAKTI', '1. PMK Nomor 154/PMK.05/2014 tentang SPAN.
2. PMK Nomor 171/PMK.05/2021 tentang Pelaksanaan Sistem SAKTI.
3. Kepdirjen Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN', NULL, NULL, NULL, '1. Setiap peminjaman user SPAN/SAKTI KPPN selaku BUN wajib disertai Berita Acara resmi untuk memastikan legalitas dan akuntabilitas penggunaan akses sistem.
2. Kepatuhan dalam penerbitan Berita Acara merupakan bentuk pengendalian internal untuk mencegah penyalahgunaan akses dan menjamin keamanan data keuangan negara.', 21, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (141, 'Pendaftaran dan/atau Perubahan User SAKTI Satker lingkup KPPN', 'Penilaian dilakukan berdasarkan sampling minimal 10% dari total permohonan pendaftaran/perubahan user SAKTI.', 5, 33, NULL, 0, 'Pendaftaran dan/atau Perubahan User SAKTI Satker lingkup KPPN', NULL, NULL, NULL, 'Surat Permohonan Pendaftaran/ Perubahan User SAKTI', '1. PMK Nomor 171/PMK.05/2021 tentang Pelaksanaan Sistem SAKTI.
2. Kepdirjen Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.', NULL, NULL, NULL, '1. Verifikasi terhadap permohonan user SAKTI memastikan keamanan akses sistem dan mencegah penyalahgunaan.
2. KPPN wajib memeriksa keabsahan dokumen termasuk form pendaftaran user, SK pengguna SAKTI, dan kelengkapan identitas pejabat.', 22, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (121, 'Upaya Meminimalisasi Terjadinya RPD Satker', 'Penilaian berdasarkan langkah nyata KPPN dalam melakukan pencegahan dan penanganan deviasi RPD melalui monitoring dan komunikasi aktif kepada Satker', 5, 25, NULL, 0, 'Upaya Meminimalisasi Terjadinya RPD Satker', NULL, NULL, NULL, 'Nota dinas, laporan, atau dokumentasi dalam bentuk lainnya.', '', NULL, NULL, NULL, '1. KPPN wajib melakukan pembinaan proaktif kepada Satker dengan deviasi tinggi melalui mekanisme early warning MyIntress.
2. Tindakan preventif mencerminkan tanggung jawab KPPN dalam menjaga efektivitas perencanaan kas dan disiplin RPD Satker.', 2, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (122, 'Prosedur Penerbitan SP2D', 'Berdasarkan uji sampling terhadap 10 pelaksanaan SOP Penerbitan SP2D untuk menilai kesesuaian proses bisnis dengan ketentuan yang berlaku.', 5, 26, NULL, 0, 'Prosedur Penerbitan SP2D', NULL, NULL, NULL, 'Ada/Tidaknya Temuan dalam Pelaksanaan Uji Sampel ', '1. PMK Nomor 171/PMK.01/2021 tentang Pelaksanaan Sistem SAKTI sebagaimana telah diubah dengan PMK Nomor 158 Tahun 2023 tentang Perubahan atas PMK Nomor 171/PMK.05/2021 tentang Pelaksanaan Sistem SAKTI.
2. PMK Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan sebagaimana telah diubah dengan PMK Nomor 107 Tahun 2024 tentang Perubahan Atas PMK Nomor.
3. Perdirjen Perbendaharaan Nomor PER-7/PB/2023 tentnag Petunjuk Teknis Pelaksanaan Belanja Pegawai dan Belanja Operasional dalam Piloting Pembayaran dalam rangka Pelaksanaan APBN melalui PPP.
4. Kepdirjen Perbendaharaan Nomor KEP-57/PB/2023 tentang Standar Pelayanan DJPb.
5. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.
6. Kepdirjen Perbendaharaan Nomor KEP-7/PB/2026 tentang Implementasi Simplifikasi Pembayaran Tagihan Belanja atas Beban APBN', NULL, NULL, NULL, '1. Kepatuhan penerbitan SP2D sesuai SOP pengukuran efektivitas pengendalian internal.
2. Setiap temuan ketidaksesuaian perlu ditindaklanjuti melalui analisis akar masalah untuk memperkuat second line of defense dan mencegah berulangnya kesalahan.
3. KPPN perlu melakukan analisis anomali belanja berdasarkan data historis satker sebagai bagian dari proses pengendalian, misalnya namun tidak terbatas pada:
a. memeriksa konsistensi penyerapan belanja tunjangan kinerja (tukin);
b. mengidentifikasi pola pengajuan tagihan yang tidak wajar;
c. membandingkan deviasi realisasi terhadap pola belanja tahun sebelumnya,', 3, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (123, 'Ketepatan Waktu Penyelesaian Tagihan', 'Penilaian dilakukan berdasarkan ketepatan waktu persetujuan tagihan oleh Kepala Seksi PD/PDMS dalam proses penerbitan SP2D sesuai Tata Cara Pembayaran APBN. Keterlambatan penerbitan SP2D yang disebabkan gangguan sistem/force majeure wajib disertai Berita Acara Penyelesaian Keterlambatan.', 5, 26, NULL, 0, 'Ketepatan Waktu Penyelesaian Tagihan', NULL, NULL, NULL, '- Monitoring Penyelesaian SP2D pada My Intress
- Berita Acara Penyelesaian Keterlambatan', '1. PMK Nomor 107 Tahun 2024 tentang Perubahan atas PMK Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan
2. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.
3. Kepdirjen Perbendaharaan Nomor KEP-7/PB/2026 tentang Implementasi Simplifikasi Pembayaran Tagihan Belanja atas Beban APBN', NULL, NULL, NULL, '1. Ketepatan waktu penerbitan SP2D mencerminkan efektivitas layanan dan kepatuhan SOP.
2. BA Penyelesaian Keterlambatan wajib digunakan sebagai bukti formal apabila terjadi gangguan teknis.', 4, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (124, 'Tindak lanjut atas Retur SP2D 

*) Retur TKD dikecualikan dalam perhitungan', 'Pengukuran dilakukan menggunakan data MyIntress dengan formula:
(Σ(Retur diproses>8 Hari Kerja)/(Σ(transaksi retur)  x 100%', 5, 26, NULL, 0, 'Tindak lanjut atas Retur SP2D 

*) Retur TKD dikecualikan dalam perhitungan', NULL, NULL, NULL, '- Tangkapan Layar monitoring retur Myintres
- Hasil perhitungan', '1. PMK Nomor 188/PMK.05/2017 tentang Tata Cara Penyaluran Dana Surat Perintah Pencairan Dana Melalui Sistem Perbendaharaan dan Anggaran Negara sebagaimana diubah dengan PMK Nomor 158/PMK.05/2022 tentang Perubahan Kedua atas PMK Nomor 188/PMK.05/2017 tentang Tata Cara Penyaluran Dana Surat Perintah Pencairan Dana Melalui Sistem Perbendaharaan dan Anggaran Negara. 
2. Perdirjen Perbendaharaan Nomor PER-9/PB/2018 tentang Tata Cara Penyelesaian Retur Surat Perintah Pencairan Dana (SP2D).
3. Kepdirjen Perbendaharaan Nomor KEP-57/PB/2023 tentang Standar Pelayanan DJPb.
4. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.
5. Kepdirjen Perbendaharaan Nomor KEP-7/PB/2026 tentang Implementasi Simplifikasi Pembayaran Tagihan Belanja atas Beban APBN', NULL, NULL, NULL, '1. Penyelesaian retur <= 3% menunjukkan efektivitas pengendalian dan ketepatan proses penyelesaian dana.
2. KPPN wajib mengidentifikasi akar penyebab retur (rekening invalid, akun salah, data ganda) dan melakukan upaya pencegahan berulang.
3. Monitoring retur melalui MyIntress merupakan mekanisme deteksi dini risiko kesalahan pembayaran.', 5, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (125, 'Kesesuaian Prosedur Penerbitan SP2B BLU', 'Penilaian berdasarkan uji sampling terhadap 3 penerbitan SP2B BLU untuk menilai kepatuhan terhadap SOP pengesahan belanja BLU.', 5, 26, NULL, 0, 'Kesesuaian Prosedur Penerbitan SP2B BLU', NULL, NULL, NULL, '- Dokumen sampling penerbitan SP2B BLU
- Dokumen temuan ketidaksesuaian proses bisnis dengan SOP (apabila ada temuan)', '1. Perdirjen Perbendaharaan Nomor PER-2/PB/2015 tentang Perubahan atas Perdirjen Nomor PER-30/PB/2011 tentang Mekanisme Pengesahan Pendapatan dan Belanja Satuan Kerja Badan Layanan Umum.
2. Kepdirjen Perbendaharaan Nomor KEP-57/PB/2023 tentang Standar Pelayanan DJPb.
3. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.', NULL, NULL, NULL, '1. SP2B BLU wajib diterbitkan sesuai SOP untuk menjaga akuntabilitas dan ketertiban pengesahan belanja BLU.
2. Verifikasi dokumen harus dilakukan secara cermat untuk memperkuat pengendalian intern dan akurasi laporan keuangan BUN.', 6, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (126, 'Kesesuaian prosedur penerbitan MPHL-BJS, SPHL, dan SP3HL', 'Penilaian dilakukan melalui uji sampling atas 10 penerbitan masing-masing dokumen untuk menilai kepatuhan terhadap SOP dan kelengkapan dokumen pengesahan hibah langsung.', 5, 26, NULL, 0, 'Kesesuaian prosedur penerbitan MPHL-BJS, SPHL, dan SP3HL', NULL, NULL, NULL, '- Dokumen sampling penerbitan MPHL-BJS
- Dokumen temuan ketidaksesuaian proses bisnis dengan SOP (apabila ada temuan)', '1. PMK Nomor 99/PMK.05/2017 tentang Administrasi Pengelolaan Hibah.
2. Kepdirjen Perbendaharaan Nomor KEP-57/PB/2023 tentang Standar Pelayanan DJPb.
3. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.', NULL, NULL, NULL, '1. Kepatuhan SOP penerbitan MPHL BJS/SP3HL/SPHL mencerminkan transparansi dan akuntabilitas pengelolaan hibah.
2. KPPN wajib memastikan validitas dokumen sumber sebelum pengesahan untuk menjamin keandalan laporan BUN.
3. Verifikasi harus mengikuti prinsip ketertiban administrasi dan pencegahan kesalahan material.', 7, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (142, 'Pendaftaran dan/atau Perubahan OTP Pejabat pada SAKTI Satker lingkup KPPN', 'Penilaian dilakukan berdasarkan sampling minimal 10% permohonan pendaftaran/perubahan OTP SAKTI.', 5, 33, NULL, 0, 'Pendaftaran dan/atau Perubahan OTP Pejabat pada SAKTI Satker lingkup KPPN', NULL, NULL, NULL, 'Surat Permohonan Pendaftaran/ Perubahan OTP SAKTI oleh Satker Dokumen persyaratan', '1. PMK Nomor 171/PMK.05/2021 tentang Pelaksanaan Sistem SAKTI.
2. Kepdirjen Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN', NULL, NULL, NULL, '1. KPPN memastikan setiap permohonan pendaftaran atau perubahan nomor telepon OTP pejabat pada aplikasi SAKTI Satker diproses sesuai prosedur dan didukung dokumen lengkap.
2. Kelengkapan dokumen menjadi jaminan keabsahan identitas pengguna dan pencegahan potensi penyalahgunaan akses sistem.
3. KPPN berperan memastikan keamanan autentikasi sistem SAKTI melalui validasi data OTP pejabat Satker.', 23, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (127, 'Pengelolaan Data Supplier', 'Penilaian dilakukan berdasarkan 5 (lima) uji sampling pendaftaran data supplier, 5 (lima) uji sampling perubahan data supplier, dan 5 (lima) uji sampling penonaktifan data supplier untuk menilai kepatuhan prosedur dan validitas data dalam sistem pembayaran.', 5, 27, NULL, 0, 'Pengelolaan Data Supplier', NULL, NULL, NULL, '- Dokumen sampling pendaftaran supplier
- Dokumen temuan ketidaksesuaian proses bisnis dengan SOP (apabila ada temuan)', '1. PMK Nomor 154/PMK.05/2014 tentang Pelaksanaan Sistem Perbendaharaan dan Anggaran Negara sebagaimana telah diubah dengan PMK Nomor 278/PMK.05/2014 tentang Perubahan atas PMK Nomor 154/PMK.05/2014 tentang Pelaksanaan Sistem Perbendaharaan dan Anggaran Negara.
2. PMK Nomor 171/PMK.05/2021 tentang Pelaksanaan Sistem SAKTI.
3. Perdirjen Perbendaharaan Nomor PER-58/PB/2013 tentang Pengelolaan Data Supplier dan Data Kontrak dalam SPAN.
4. Perdirjen Perbendaharaan Nomor PER-58/PB/2013 tentang Pengelolaan Data Supplier dan Data Kontrak dalam SPAN.
5. Kepdirjen Perbendaharaan Nomor KEP-57/PB/2023 tentang Standar Pelayanan DJPb.
6. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.', NULL, NULL, NULL, '1. Pendaftaran supplier harus dilakukan sesuai prosedur dan diverifikasi kebenarannya oleh petugas KPPN sebelum aktif di sistem pembayaran.
2. KPPN wajib memastikan kebenaran data supplier yang didaftarkan ke KPPN oleh Satker.
3. Kepatuhan prosedur pendaftaran supplier mencegah risiko pembayaran tidak sah dan memperkuat integritas data pada sistem SPAN/SAKTI.', 8, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (128, 'Monitoring Penonaktifan Data Pegawai dan Data Supplier', 'Penilaian dilakukan berdasarkan 5 (lima) uji sampling penerbitan SKPP untuk memastikan penonaktifan data pegawai dan supplier yang sudah tidak aktif.', 5, 27, NULL, 0, 'Monitoring Penonaktifan Data Pegawai dan Data Supplier', NULL, NULL, NULL, '- Monitoring Penerbitan SKPP
- Tangkapan layar data pegawai dan data supplier yang aktif pada Aplikasi Gaji KPPN', '1. PMK Nomor 154/PMK.05/2014 tentang Pelaksanaan Sistem Perbendaharaan dan Anggaran Negara sebagaimana telah diubah dengan PMK Nomor 278/PMK.05/2014 tentang Perubahan atas PMK Nomor 154/PMK.05/2014 tentang Pelaksanaan Sistem Perbendaharaan dan Anggaran Negara.
2. PMK Nomor 171/PMK.05/2021 tentang Pelaksanaan Sistem SAKTI.
3. Perdirjen Perbendaharaan Nomor PER-58/PB/2013 tentang Pengelolaan Data Supplier dan Data Kontrak dalam SPAN.
4. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.', NULL, NULL, NULL, '1. SKPP harus diikuti dengan penonaktifan data pegawai dan supplier terkait untuk mencegah potensi pembayaran tidak sah atau ganda.
2. KPPN melakukan pengecekan status data pada sistem untuk memastikan penonaktifan telah dilakukan.', 9, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (129, 'Pengelolaan Data Kontrak', 'Penilaian dilakukan berdasarkan 5 (lima) uji sampling pendaftaran data kontrak dan 5 (lima) uji sampling perubahan data kontrak untuk menilai kelengkapan dokumen dan kepatuhan terhadap ketentuan.', 5, 27, NULL, 0, 'Pengelolaan Data Kontrak', NULL, NULL, NULL, 'Resume kontrak, karwas kontrak, dan Surat Permohonan sesuai format dalam Per-58/PB/2013  atau addendum aplikasi', '1. PMK Nomor 154/PMK.05/2014 tentang Pelaksanaan Sistem Perbendaharaan dan Anggaran Negara (SPAN).
2. Perdirjen Perbendaharaan Nomor PER-58/PB/2013 tentang Pengelolaan Data Supplier dan Data Kontrak dalam SPAN.
3. Kepdirjen Perbendaharaan Nomor KEP-57/PB/2023 tentang Standar Pelayanan DJPb.
4. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.
5. Kepdirjen Perbendaharaan Nomor KEP-7/PB/2026 tentang Implementasi Simplifikasi Pembayaran Tagihan Belanja atas Beban APBN', NULL, NULL, NULL, '1. Pendaftaran dan perubahan data kontrak dilakukan sesuai SOP dan disertai dokumen pendukung yang lengkap dan sah
2. KPPN memastikan kelengkapan dokumen untuk menjamin keandalan data kontrak dalam proses pengujian SPM dan penerbitan SP2D.', 10, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (137, 'Ketepatan Waktu Penyampaian LPJ Bendahara', 'Penilaian dilakukan berdasarkan uji sampling LPJ Bendahara selama tiga bulan untuk menilai ketepatan waktu penyampaian LPJ oleh satker kepada KPPN.', 5, 31, NULL, 0, 'Ketepatan Waktu Penyampaian LPJ Bendahara', NULL, NULL, NULL, 'Bukti Monitoring Penyampaian LPJ Satker pada Aplikasi SAKTI/ MONSAKTI', '', NULL, NULL, NULL, '1. KPPN memonitor ketepatan waktu penyampaian LPJ Bendahara sebagai indikator kedisiplinan dan kepatuhan satker dalam pertanggung-jawaban keuangan.
2. Ketepatan waktu penyampaian LPJ mencerminkan efektivitas pembinaan dan pengendalian internal yang dilakukan KPPN terhadap satker.', 18, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (130, 'Penggunaan KKP', 'Penilaian berdasarkan tren penggunaan Kartu Kredit Pemerintah (KKP) oleh satker lingkup KPPN selama satu semester pada periode pembinaan.', 5, 28, NULL, 0, 'Penggunaan KKP', NULL, NULL, NULL, 'Hasil monitoring realisasi KKP pada Myintress', '1. PMK Nomor 196/PMK.05/2018 tentang Tata Cara Pembayaran dan Penggunaan Kartu Kredit Pemerintah sebagaimana diubah dengan PMK Nomor 97/PMK.05/2021 tentang Perubahan atas Peraturan Menteri Keuangan Nomor 196/PMK.05/2018 Tentang Tata Cara Pembayaran dan Penggunaan Kartu Kredit Pemerintah.
2. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.', NULL, NULL, NULL, '1. Peningkatan tren penggunaan KKP mencerminkan keberhasilan digitalisasi pembayaran dan peningkatan efisiensi pengelolaan kas;
2. KPPN memastikan pemahaman satker terkait manfaat dan prosedur KKP serta melakukan pembinaan bagi satker dengan tingkat penggunaan KKP yang rendah.', 11, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (131, 'Penggunaan CMS Rekening Virtual (VA)', 'Penilaian berdasarkan tren penggunaan CMS atas Rekening Virtual (VA) satker aktif selama satu semester pada periode pembinaan.', 5, 28, NULL, 0, 'Penggunaan CMS Rekening Virtual (VA)', NULL, NULL, NULL, 'Hasil monitoring penggunaan CMS yang diperoleh dari Dashboard Bank Mitra Pengelola VA', 'Peraturan Menteri Keuangan Nomor 183/PMK.05/2019 tentang Pengelolaan Rekening Pengeluaran Milik Kementerian Negara/Lembaga', NULL, NULL, NULL, '1. Tren peningkatan penggunaan CMS mencerminkan keberhasilan implementasi digitalisasi pembayaran nontunai (cashless) dan efisiensi pengelolaan kas pemerintah;
2. KPPN perlu memastikan satker memahami manfaat dan prosedur penggunaan CMS serta melakukan pembinaan terhadap satker dengan tingkat pemanfaatan CMS yang masih rendah.', 12, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (132, 'Kepatuhan Penyetoran Sisa UP/TUP Akhir Tahun Anggaran', 'Penilaian dilakukan berdasarkan hasil monitoring melalui Aplikasi MyIntress dan konfirmasi kepada KPPN mengenai kepatuhan satker dalam menyetor sisa UP/TUP.
Ruang lingkup:
a. Semester I – menilai penyetoran sisa UP/TUP tahun anggaran sebelumnya.
b. Semester II – menilai sisa UP/TUP yang belum disetor pada Semester I.

Pengecualian:
UP/TUP valas pada Satker Perwakilan/Atase Teknis LN dan UP/TUP Pengembalian PPN Turis Asing pada Satker KPP.
', 5, 29, NULL, 0, 'Kepatuhan Penyetoran Sisa UP/TUP Akhir Tahun Anggaran', NULL, NULL, NULL, 'Monitoring setoran UP/TUP tahun anggaran berjalan', '1. PMK Nomor 188/PMK.05/2021 tentang Tata Cara Pembayaran atas Pengembalian Penerimaan Negara.
2. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.', NULL, NULL, NULL, '1. Sisa UP/TUP wajib disetor ke Kas Negara sebelum batas akhir tahun anggaran untuk menjaga akuntabilitas pengelolaan kas pemerintah.
2. KPPN memastikan monitoring kepatuhan satker dilakukan melalui Aplikasi MyIntress dan hasilnya menjadi dasar pembinaan terhadap satker yang terlambat menyetor. ', 13, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (133, 'Penerbitan Surat Pemberitahuan/
Teguran Pengajuan Penggantian Uang Persediaan', 'Penilaian dilakukan melalui uji sampling terhadap 10 satker yang tidak melakukan revolving UP setiap bulan, untuk memastikan kepatuhan KPPN dalam menerbitkan surat pemberitahuan penggantian UP.', 5, 29, NULL, 0, 'Penerbitan Surat Pemberitahuan/
Teguran Pengajuan Penggantian Uang Persediaan', NULL, NULL, NULL, 'Surat Pemberitahuan Pengajuan Penggantian Uang Persediaan', '1. PMK Nomor 107 Tahun 2024 tentang Perubahan atas PMK Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan
2. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.', NULL, NULL, NULL, '1. Surat pemberitahuan berfungsi sebagai mekanisme kontrol awal untuk menjaga ketersediaan dana operasional satker.
2. KPPN melakukan pembinaan melalui penerbitan surat pemberitahuan kepada satker yang tidak melakukan penggantian UP sesuai ketentuan.
3. Penerbitan surat pemberitahuan menjadi bukti nyata pelaksanaan fungsi pembinaan dan pengawasan terhadap efektivitas penggunaan UP oleh satker.', 14, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (134, 'Pengelolaan Rekening Satker', 'Penilaian dilakukan melalui uji sampling atas 5 permohonan pembukaan dan 5 permohonan penutupan rekening satker untuk menilai kesesuaian proses dengan ketentuan yang berlaku.', 5, 30, NULL, 0, 'Pengelolaan Rekening Satker', NULL, NULL, NULL, '- Dokumen sampling pembukaan rekening Satker 
- Dokumen temuan ketidaksesuaian proses bisnis dengan SOP (apabila ada temuan', '1. PMK Nomor 182/PMK.05/2017 tentang Pengelolaan Rekening Milik Satuan Kerja Lingkup Kementerian Negara/Lembaga
2. PMK Nomor 183/PMK.05/2019 tentang Pengelolaan Rekening Pengeluaran Milik Kementerian Negara/Lembaga.
3. Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN sebagaimana diubah dengan Kepdirjen Perbendaharaan Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Perbendaharaan Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.', NULL, NULL, NULL, '1. Pembukaan rekening oleh Satker harus memperoleh persetujuan dari Kementerian Keuangan sesuai prosedur.
2. KPPN memastikan kepatuhan satker terhadap ketentuan agar tidak terdapat rekening yang dibuka tanpa izin atau di luar ketentuan yang berlaku.', 15, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (135, 'Tindak Lanjut atas Kesalahan Data Penerimaan Negara yang Tercatat pada MyIntress', 'Penilaian dilakukan terhadap langkah KPPN dalam menindaklanjuti kesalahan data penerimaan negara pada MyIntress, seperti kesalahan akun, satker, nominal, atau pemotongan.', 5, 30, NULL, 0, 'Tindak Lanjut atas Kesalahan Data Penerimaan Negara yang Tercatat pada MyIntress', NULL, NULL, NULL, 'Data Monitoring My Intress', 'Perdirjen Nomor PER-16/PB/2014 tentang tata Cara Koreksi Data Transaksi Keuangan pada SPAN.', NULL, NULL, NULL, '1. KPPN wajib melakukan kontrol dan monitoring kesalahan data penerimaan negara secara proaktif melalui MyIntress;
2. Setiap kesalahan harus ditindaklanjuti dengan surat pemberitahuan resmi kepada Satker terkait dan didokumentasikan sebagai bukti tindak lanjut.', 16, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (136, 'Akuntabilitas LPJ Bendahara Satker', 'Penilaian dilakukan sampling terhadap 10 pelaksanaan verifikasi LPJ Bendahara Satker oleh KPPN.', 5, 31, NULL, 0, 'Akuntabilitas LPJ Bendahara Satker', NULL, NULL, NULL, '- Bukti penyelesaian verifikasi LPJ pada Aplikasi SAKTI.
- Dokumen temuan ketidaksesuaian proses bisnis (apabila ada).', '1. PMK Nomor 162/PMK.05/2013 tentang Kedudukan dan Tanggung Jawab Bendahara pada Satker Pengelola APBN sebagaimana telah diubah dengan PMK Nomor 230/PMK.05/2016.
2. Perdirjen Nomor PER-3/PB/2014 tentang Petunjuk Teknis Penatausahaan, Pembukuaan, dan Pertanggungjawaban Bendahara pada Satuan Kerja Pengelola Anggaran Pendapatan dan Belanja Negara serta Verifikasi Laporan Pertanggungjawaban Bendahara.
3. Perdirjen yang lain, yaitu PER-47/PB/2014 tentang Petunjuk Teknis Penatausahaan, Pembukuan, dan Pertanggungjawaban Bendahara pada BLU serta Verifikasi dan Monitoring LPJ Bendahara pada BLU.', NULL, NULL, NULL, '1. KPPN wajib melaksanakan verifikasi LPJ Bendahara sesuai ketentuan SOP mengenai verifikasi LPJ Bendahara;
2. Verifikasi mencakup uji validitas dan kelengkapan dokumen LPJ untuk memastikan akuntabilitas dan keandalan pelaporan keuangan satker.', 17, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (138, 'Upaya Tindak Lanjut Penyelesaian To Do List Kualitas Data Laporan Keuangan', 'Penilaian dilakukan berdasarkan hasil monitoring To Do List pada MyIntress untuk mengukur ketepatan dan efektivitas tindak lanjut KPPN.', 5, 32, NULL, 0, 'Upaya Tindak Lanjut Penyelesaian To Do List Kualitas Data Laporan Keuangan', NULL, NULL, NULL, '- Bukti Monitoring to do list pada Aplikasi My Intress
- Bukti tindak lanjut atas to do list (contoh: surat pemberitahuan ke Satker)', 'PMK Nomor 107 Tahun 2024 tentang Perubahan atas PMK Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan', NULL, NULL, NULL, '1. KPPN wajib melakukan tindak lanjut terhadap seluruh to do list kualitas data laporan keuangan yang muncul pada Aplikasi MyIntress.
2. Tindak lanjut yang dilakukan menjadi pengukuran efektivitas fungsi pengendalian kualitas data laporan keuangan satker oleh KPPN. ', 19, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (139, 'Tindak Lanjut Hasil Analisis Data Transaksi Keuangan pada SPAN', 'Penilaian dilakukan terhadap tindak lanjut KPPN atas anomali data transaksi keuangan pada SPAN', 5, 32, NULL, 0, 'Tindak Lanjut Hasil Analisis Data Transaksi Keuangan pada SPAN', NULL, NULL, NULL, '- Kertas kerja analisis
- ND/surat teguran/tindak lanjut', 'Perdirjen nomor PER-56/PB/2016 tentang Pedoman Analisis Laporan Keuangan Unit Akuntansi Dan Pelaporan Keuangan Kuasa Bendahara Umum Negara Tingkat Kantor Pelayanan Perbendaharaan Negara dan Unit Akuntansi dan Pelaporan Keuangan Koordinator Kuasa Bendahara Umum Negara Tingkat Kantor Wilayah', NULL, NULL, NULL, 'KPPN wajib menindaklanjuti anomali melalui verifikasi, klarifikasi, dan pemberian rekomendasi perbaikan kepada satker.', 20, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (143, 'Pengelolaan Join Domain dan Keamanan Informasi Perangkat Pengguna', 'Penilaian didasarkan pada kelengkapan administrasi dan kepatuhan terhadap standar keamanan perangkat atas uji sampling minimal 10% dari seluruh perangkat aktif:', 5, 33, NULL, 0, 'Pengelolaan Join Domain dan Keamanan Informasi Perangkat Pengguna', NULL, NULL, NULL, '- SK/Nota Dinas Penunjukkan PIC TIK pada Unit di tahun berjalan
- Screenshot Status Perangkat sudah Terjoin Domain
- Formulir Penguatan Keamanan Informasi', '1. KMK Nomor 411/KMK.01/2023 Tentang Keamanan Informasi, Keamanan Siber, dan Perlindungan Data Pribadi di Lingkungan Kementerian Keuangan.
2. Surat Edaran Nomor SE-19/MK.1/2018 Tentang Implemetasi Join Domain Perangkat Teknologi Informasi dan Komunikasi dan Perangkat Pengguna di Lingkungan Kementerian Keuangan.
3. Keputusan CIO Nomor 01/SA.8/2024 Tentang Manajemen Perangkat Teknologi Informasi dan Komunikasi di Lingkungan Kementerian Keuangan.
4. Peraturan Direktur Jenderal Perbendaharaan nomor PER-1/PB/2021 tentang Kebijakan Sistem Manajemen Keamanan Informasi di Lingkungan Direktorat Jenderal Perbendaharaan.', NULL, NULL, NULL, '1. Setiap Perangkat TIK dan Perangkat Pengguna (PC, Laptop pada unit KPPN dan Kanwil) harus terdaftar pada sistem domain kemenkeu.go.id dan harus mengikuti struktur domain kemenkeu.go.id;
2. Pengguna dalam hal ini pegawai pada unit KPPN dan Kanwil memiliki tanggung jawab untuk menjaga keamanan informasi dalam penggunaan Perangkat Pengguna (PC dan/atau Laptop)', 24, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (144, 'Penyaluran DAK Fisik dan Dana Desa', 'Membandingkan data realisasi penyaluran DAK Fisik dan Dana Desa pada aplikasi MyIntress dengan ketentuan target penyaluran di setiap tahapan.', 5, 34, NULL, 0, 'Penyaluran DAK Fisik dan Dana Desa', NULL, NULL, NULL, 'Data realisasi penyaluan TKD pada Aplikasi MyIntress', '1. PMK Nomor 198/PMK.07/ 2021 tentang DAK Fisik
2. PMK Nomor 108 Tahun 2024 tentang Dana Desa
3. Perdirjen Nomor PER-7/PB/2020 tentang Petunjuk Teknis Penyaluran DAK Fisik pada DJPb
4. Perdirjen Nomor PER-3/PB/2021 tentang Petunjuk Teknis Penyaluran Dana Desa pada DJPb', NULL, NULL, NULL, '1. KPPN wajib memastikan pelaksanaan penyaluran DAK Fisik dan Dana Desa sesuai tahapan dan jadwal penyaluran yang ditetapkan.
2. Monitoring deviasi realisasi dilakukan untuk mengukur efektivitas koordinasi KPPN dengan Pemda serta kecepatan proses verifikasi dokumen penyaluran.
3. Deviasi <=15% menunjukkan penyaluran yang sesuai ketentuan dan responsif terhadap target kinerja fiskal daerah', 25, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (145, 'Ketepatan Data Debitur dan Penyaluran Umi', 'Penilaian dilakukan berdasarkan kegiatan pencocokan data oleh KPPN terhadap data debitur yang tercatat dalam SIKP-UMi pada periode triwulan berjalan.', 5, 35, NULL, 0, 'Ketepatan Data Debitur dan Penyaluran Umi', NULL, NULL, NULL, 'Data debitur UMi, data SIKP UMi, Konfirmasi dokumen tidak dapat diperoleh dari Penyalur (bila dokumen tidak dapat diperoleh).', 'PMK Nomor 130/2024 tentang Pembiayaan Usaha Mikro, Kecil, dan Menengah pada Pusat Investasi Pemerintah.', NULL, NULL, NULL, '1. KPPN wajib melakukan koordinasi aktif dengan penyalur UMi untuk memperoleh data debitur secara lengkap dan tepat waktu.
2. Validasi dilakukan dengan mencocokkan dokumen penyalur (fisik/elektronik) dengan data yang tercatat dalam SIKP-UMi untuk menjaga akurasi penyaluran.
3. Apabila data tidak tersedia dari penyalur, KPPN harus melakukan pencatatan pada SIKP-UMi disertai keterangan yang jelas.
4. Tingkat pencocokan data mencerminkan keandalan akurasi pelaporan dan kualitas penyaluran UMi pada wilayah kerja KPPN.', 26, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (146, 'Analisis dan Rekomendasi KPPN terkait Implementasi Pelaksanaan Anggaran Satker APBN', 'Penilaian dilakukan berdasarkan Laporan Analisis Kinerja Pelaksanaan Anggaran yang disusun Pejabat Fungsional PTPN untuk menilai kualitas analisis permasalahan dan rekomendasi KPPN.', 6, 36, NULL, 0, 'Analisis dan Rekomendasi KPPN terkait Implementasi Pelaksanaan Anggaran Satker APBN', NULL, NULL, NULL, 'Laporan Analisis Kinerja Pelaksanaan Anggaran Satker lingkup KPPN', 'PMK Nomor 107 Tahun 2024 tentang Perubahan atas PMK Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaktsanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan', NULL, NULL, NULL, '1. Analisis diarahkan untuk mengidentifikasi hambatan terhadap perencanaan anggaran belanja lingkup Satker.
2. Hasil analisis dan rekomendasi digunakan untuk pembinaan lanjutan kepada Satker dan sebagai masukan kebijakan (policy feedback), serta untuk mendukung peran Kanwil DJPb sebagai Regional Chief Economist (RCE).', 1, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (147, 'Analisa dan Rekomendasi KPPN terkait Tantangan Penyaluran Belanja TKD', 'Penilaian dilakukan berdasarkan laporan monitoring dan evaluasi (monev) TKD yang disusun KPPN', 6, 37, NULL, 0, 'Analisa dan Rekomendasi KPPN terkait Tantangan Penyaluran Belanja TKD', NULL, NULL, NULL, 'Laporan Monev TKD', 'PMK Nomor 107 Tahun 2024 tentang Perubahan atas PMK Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaktsanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan.', NULL, NULL, NULL, '1. Analisis diarahkan untuk mengidentifikasi hambatan terhadap penyaluran TKD lingkup Pemda.
2. Hasil analisis dan rekomendasi digunakan untuk pembinaan lanjutan kepada Pemda dan sebagai masukan kebijakan (policy feedback), serta untuk mendukung peran Kanwil DJPb sebagai Regional Chief Economist (RCE).', 2, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (157, 'Pelaksanaan Monev terkait Central Government Advisory', 'Berdasarkan analisis permasalahan dan capaian kinerja satker, KPPN melaksanakan kegiatan monitoring dan evaluasi (Monev) terhadap pelaksanaan anggaran satker, baik secara langsung maupun daring, dalam rangka pelaksanaan fungsi Central Government Advisory.', 7, 40, 23, 0, 'Pelaksanaan Monev terkait Central Government Advisory', NULL, NULL, NULL, 'Laporan/bukti dukung kegiatan monev terkait Central Government Advisory', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb', NULL, NULL, NULL, '1. Monev merupakan bentuk pembinaan aktif dan berkelanjutan berbasis data analitik, untuk mengidentifikasi permasalahan dan memperbaiki kualitas pelaksanaan anggaran satker.
2. Pelaksanaan Monev secara periodik menunjukkan peran KPPN sebagai financial advisor yang adaptif, responsif, dan strategis dalam mendukung pencapaian kinerja fiskal pemerintah.', 7, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (148, 'Penilaian Pelaksanaan Analisis dan Pelaporan Data Penerimaan Dana PFK Pegawai', 'Penilaian dilakukan terhadap pelaksanaan analisis data PFK Pegawai pada OM SPAN serta ketepatan waktu penyampaian Laporan Hasil Analisis Data PFK Pegawai oleh KPPN.', 6, 38, NULL, 0, 'Penilaian Pelaksanaan Analisis dan Pelaporan Data Penerimaan Dana PFK Pegawai', NULL, NULL, NULL, 'Data OMSPAN, Nota dinas, laporan, atau dokumentasi dalam bentuk lainnya.', '1. Peraturan Menteri Keuangan Nomor 156/PMK.05/2019 tentang Dana Perhitungan Fihak Ketiga sebagaimana telah diubah dengan Peraturan Menteri Keuangan 212/PMK.05/2020 tentang Peraturan Menteri Keuangan Nomor 156/PMK.05/2019 tentang Dana Perhitungan Fihak Ketiga.
2. Peraturan Direktorat Jenderal Perbendaharaan Nomor PER-33/PB/2017 tentang Petunjuk Pelaksanaan Analisis Dan Konsolidasi Data Penerimaan Dana Perhitungan Fihak Ketiga Pegawai Pada Instansi Vertikal Direktorat Jenderal Perbendaharaan.', NULL, NULL, NULL, '1. KPPN menganalisis Data Penerimaan Dana PFK Pegawai yang terdapat dalam Aplikasi OM SPAN Modul Monitoring PFK untuk meningkatkan akurasi data.
2. Tindak lanjut konfirmasi kepada satuan kerja di wilayahnya menjadi indikator tanggung jawab KPPN dalam menjaga akurasi Data Penerimaan Dana PFK Pegawai.', 3, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (150, 'Upaya Percepatan Konversi Level Sertifikasi Kompetensi Pejabat Perbendaharaan', 'ilaian dilakukan terhadap langkah KPPN dalam mempercepat pemenuhan dan konversi level sertifikasi kompetensi Pejabat Perbendaharaan melalui kegiatan pembinaan dan pemberitahuan pelaksanaan sertifikasi kepada satker.', 7, 40, 21, 0, 'Upaya Percepatan Konversi Level Sertifikasi Kompetensi Pejabat Perbendaharaan', NULL, NULL, NULL, 'Bukti upaya percepatan leveling sertifikasi kompetensi pejabat perbendaharaan (misalnya Surat, Undangan, Daftar Hadir, Monitoring Data Sertifikasi Pejabat Perbendaharaan)
', '1. PMK Nomor 211/PMK.05/2019 tentang Sertifikasi Bendahara, Pejabat Perbendaharaan, dan Pengelola APBN.
2. Perdirjen Perbendaharaan Nomor PER-22/PB/2020 tentang Petunjuk Teknis Pelaksanaan Sertifikasi Pejabat Perbendaharaan.
3. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.', NULL, NULL, NULL, '1. KPPN wajib internalisasi dan percepatanuntuk melakukan konversi level sertifikasi kompetensi pejabat perbendaharaan.
2. Upaya aktif menjadi indikator peran advisory KPPN dalam meningkatkan kompetensi dan profesionalisme pengelola keuangan negara di Satker.
3. Peningkatan jumlah pejabat tersertifikasi mendukung tata kelola keuangan yang akuntabel', 1, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (151, 'Sertifikasi Kompetensi Pejabat Perbendaharaan', 'Penilaian dilakukan terhadap tingkat persentase pejabat perbendaharaan Satker (PPK, PPSPM, Bendahara) lingkup KPPN yang telah memiliki sertifikat kompetensi, dengan formula:

(Σ(Pejabat Perbendaharaan Satker telah tersertifikasi)/(Σ(Seluruh Pejabat Perbendaharaan Satker Lingkup KPPN) x 100%', 7, 40, 21, 0, 'Sertifikasi Kompetensi Pejabat Perbendaharaan', NULL, NULL, NULL, '1. Data pejabat perbendaharaan tersertifikasi dan belum tersertifikasi (dari Aplikasi Sertifikasi Perbendaharaan atau monitoring KPPN).
2. Rekapitulasi hasil perhitungan tingkat pemenuhan sertifikasi pejabat perbendaharaan.', '1. PMK Nomor 211/PMK.05/2019 tentang Sertifikasi Bendahara, Pejabat Perbendaharaan, dan Pengelola APBN.
2. Perdirjen Perbendaharaan Nomor PER-22/PB/2020 tentang Petunjuk Teknis Pelaksanaan Sertifikasi Pejabat Perbendaharaan.
3. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.', NULL, NULL, NULL, '1. Tingkat pemenuhan sertifikasi mencerminkan kualitas pembinaan dan efektivitas koordinasi KPPN dengan satker dalam pelaksanaan sertifikasi pejabat perbendaharaan.
2. KPPN wajib memonitor dan memperbarui data pejabat tersertifikasi secara berkala melalui aplikasi sertifikasi dan komunikasi dengan satker.', 2, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (152, 'Pembinaan implementasi Jabatan Fungsional Keuangan Negara Bidang Perbendaharaan', 'Pelaksanaan monev dan penyelesaian tindak lanjut hasil monev atas implementasi JF Keuangan Negara Bidang Perbendaharaan pada satker mitra.', 7, 40, 21, 0, 'Pembinaan implementasi Jabatan Fungsional Keuangan Negara Bidang Perbendaharaan', NULL, NULL, NULL, 'Laporan hasil monev implementasi JF Keuangan Negara Bidang Perbendaharaan', '1. PMK Nomor 163/PMK.05/2022 tentang Perubahan atas PMK Nomor 150/PMK.05/2019 tentang Juknis JF APK APBN.
2. PMK Nomor 162/PMK.05/2022 tentang Perubahan atas PMK Nomor 151/PMK.05/2019 tentang Juknis JF PK APBN.
3. Kepdirjen Perbendaharaan Nomor KEP-158/PB/2021 tentang Pelaksanaan Tugas Unit Pembina Teknis Jabatan Fungsional di Lingkungan Ditjen Perbendaharaan.', NULL, NULL, NULL, 'KPPN wajib memastikan bahwa JF Keuangan Negara Bidang Perbendaharaan pada satuan kerja mitra telah memutakhirkan data pada aplikasi e-jafung', 3, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (153, 'FGD/Sharing Session terkait Central Government Advisory', 'Kegiatan FGD/Sharing Session yang dilaksanakan KPPN dengan materi di antaranya namun tidak terbatas pada digitalisasi pembayaran; laporan keuangan pemerintah; keuangan negara dan fiskal; penguatan pelaksanaan anggaran berbasis kinerja.', 7, 40, 22, 0, 'FGD/Sharing Session terkait Central Government Advisory', NULL, NULL, NULL, '- Laporan pelaksanaan kegiatan; dan/atau
- Bukti keterlibatan kegiatan FGD/Sharing Session (misalnya ST/ Undangan, Daftar Hadir)', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb.', NULL, NULL, NULL, '1. FGD/Sharing Session merupakan media pembinaan dan pertukaran pengetahuan untuk memperkuat pemahaman satker terhadap kebijakan perbendaharaan dan keuangan negara.
2. Pelaksanaan kegiatan secara rutin menunjukkan komitmen KPPN dalam menjalankan peran FA.
3. Kegiatan FGD yang efektif meningkatkan kualitas tata kelola dan mendorong perbaikan capaian kinerja satker dalam mengelola APBN.', 4, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (154, 'Sosialisasi/ Bimtek terkait Central Government Advisory', 'Kegiatan sosialisasi atau bimbingan teknis yang dilaksanakan oleh KPPN kepada satker lingkup wilayah kerja dengan materi di antaranya namun tidak terbatas pada digitalisasi pembayaran; laporan keuangan pemerintah; keuangan negara dan fiskal; penguatan pelaksanaan anggaran berbasis kinerja.', 7, 40, 22, 0, 'Sosialisasi/ Bimtek terkait Central Government Advisory', NULL, NULL, NULL, 'Laporan pelaksanaan kegiatan Sosialisasi/
Bimtek', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb.', NULL, NULL, NULL, '1. Sosialisasi dan Bimtek merupakan bentuk pembinaan berkelanjutan (continuous advisory) dalam rangka peningkatan pemahaman satker terhadap kebijakan fiskal dan operasional perbendaharaan.
2. Pelaksanaan kegiatan yang rutin dan terdokumentasi menunjukkan peran aktif KPPN sebagai advisor bagi Satker.
3. Efektivitas kegiatan dapat tercermin dari perbaikan kepatuhan satker, peningkatan kualitas pelaksanaan anggaran, serta penurunan tingkat kesalahan atau deviasi indikator kinerja.', 5, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (158, 'Hasil dan Tindak Lanjut Monev terkait Central Government Advisory', 'Berdasarkan hasil pelaksanaan Monev terhadap satuan kerja dalam rangka Central Government Advisory, KPPN menyusun laporan hasil Monev berupa pemetaan permasalahan satker dan menindaklanjuti hasil tersebut melalui rekomendasi, solusi, dan/atau langkah perbaikan lainnya.', 7, 40, 23, 0, 'Hasil dan Tindak Lanjut Monev terkait Central Government Advisory', NULL, NULL, NULL, 'laporan/bukti dukung kegiatan tindak lanjut monev terkait Central Government Advisory', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb', NULL, NULL, NULL, '1. KPPN mampu mengonversi hasil Monev menjadi rekomendasi dan tindak lanjut nyata yang berorientasi pada perbaikan kinerja satuan kerja.
2. Hasil tindak lanjut Monev mencerminkan fungsi analitis dan advisory KPPN dalam mendukung efektivitas pelaksanaan anggaran satker.
3. Dokumentasi hasil dan tindak lanjut Monev menjadi bukti pelaksanaan pembinaan berkelanjutan dan perbaikan berbasis data analitik.', 8, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (159, 'FGD/Sharing Session terkait Local Government Advisory', 'Berdasarkan penyelenggaraan kegiatan atau keterlibatan KPPN dalam FGD/Sharing Session bersama Pemerintah Daerah, dengan materi di antaranya namun tidak terbatas pada pengendalian dan mitigasi inflasi daerah; evaluasi penyaluran dan pemanfaatan TKD; sinkronisasi pengelolaan APBD ; dan penguatan fiskal daerah.', 7, 41, 24, 0, 'FGD/Sharing Session terkait Local Government Advisory', NULL, NULL, NULL, '- Laporan pelaksanaan kegiatan; dan/atau
- Bukti keterlibatan kegiatan FGD/Sharing Session (misalnya ST/ Undangan, Daftar Hadir)', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb', NULL, NULL, NULL, '1. FGD/Sharing Session merupakan bentuk penguatan fungsi advisory KPPN sebagai mitra kebijakan (policy partner) Pemerintah Daerah dalam mendorong efektivitas penyaluran TKD dan pertumbuhan ekonomi daerah.
2. Kegiatan ini mencerminkan kematangan peran KPPN sebagai Local Fiscal Advisor, tidak hanya berfungsi administratif, tetapi juga konsultatif dan strategis.', 9, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (160, 'Sosialisasi/ Bimtek terkait Local Government Advisory', 'Berdasarkan kegiatan sosialisasi/bimtek yang dilakukan oleh KPPN dengan materi terkait proses perencanaan, persyaratan penyaluran, penggunaan, dan/atau pertanggungjawaban dana TKD', 7, 41, 24, 0, 'Sosialisasi/ Bimtek terkait Local Government Advisory', NULL, NULL, NULL, 'Laporan pelaksanaan kegiatan Sosialisasi/ Bimtek', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb', NULL, NULL, NULL, '1.Kegiatan Sosialisasi/Bimtek merupakan sarana pembinaan dan peningkatan kapasitas Pemda dalam memahami siklus penyaluran TKD dari perencanaan hingga pertanggung-jawaban.
2. Pemahaman yang baik atas ketentuan TKD akan mengurangi risiko keterlambatan, retur dokumen, maupun ketidaktepatan pelaporan.
3. Melalui kegiatan ini, KPPN menunjukkan perannya sebagai Local Fiscal Advisor yang aktif, edukatif, dan berorientasi pada peningkatan kualitas pengelolaan keuangan daerah', 10, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (161, 'Helpdesk', 'Berdasarkan permasalahan yang timbul dalam proses penyaluran TKD oleh Pemda, KPPN melakukan fungsi helpdesk dengan berkoordinasi dan memberikan asistensi guna menyelesaikan permasalahan dimaksu', 7, 41, 24, 0, 'Helpdesk', NULL, NULL, NULL, '- Laporan pelaksanaan kegiatan; dan/atau
- Bukti keterlibatan kegiatan FGD/Sharing Session (misalnya ST/ Undangan, Daftar Hadir)', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb', NULL, NULL, NULL, '1. KPPN berperan sebagai penghubung fiskal (fiscal intermediary) antara Pemerintah Pusat dan Pemerintah Daerah dalam memastikan kelancaran penyaluran TKD.
2. Penyelesaian masalah TKD secara cepat dan akurat mendukung percepatan realisasi anggaran daerah dan menjaga kesinambungan pelayanan publik.', 11, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (162, 'Pelaksanaan Monev terkait Local Government Advisory', 'Berdasarkan hasil analisis terhadap permasalahan penyaluran TKD, KPPN melaksanakan kegiatan monev kepada Pemda secara langsung atau daring, serta dapat berkolaborasi dengan Kanwil DJPb.', 7, 41, 25, 0, 'Pelaksanaan Monev terkait Local Government Advisory', NULL, NULL, NULL, 'Laporan/bukti dukung kegiatan monev terkait Local Government Advisory', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Perdirjen Nomor PER-7/PB/2020 tentang Petunjuk Teknis Penyaluran DAK Fisik pada DJPb dan Perdirjen Nomor PER-3/PB/2021 tentang Petunjuk Teknis Penyaluran Dana Desa pada DJPb', NULL, NULL, NULL, '1. Kegiatan monev harus berorientasi pada identifikasi hambatan penyaluran, peningkatan kualitas pelaporan, serta percepatan realisasi TKD.
2. Kolaborasi dengan Kanwil DJPb memperkuat fungsi koordinatif dan sinergi pembinaan kepada Pemerintah Daerah', 12, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (163, 'Hasil dan Tindak lanjut Monev terkait Local Government Advisory', 'Berdasarkan hasil pelaksanaan kegiatan monev terhadap Pemda dalam rangka Local Government Advisory, KPPN menyusun laporan hasil monev yang berisi pemetaan permasalahan penyaluran TKD dan melakukan tindak lanjut berupa rekomendasi, solusi, dan/atau langkah perbaikan sesuai hasil monev.', 7, 41, 25, 0, 'Hasil dan Tindak lanjut Monev terkait Local Government Advisory', NULL, NULL, NULL, 'laporan/bukti dukung kegiatan tindak lanjut monev terkait Local Government Advisory', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Perdirjen Nomor PER-7/PB/2020 tentang Petunjuk Teknis Penyaluran DAK Fisik pada DJPb dan
3. Perdirjen Nomor PER-3/PB/2021 tentang Petunjuk Teknis Penyaluran Dana Desa pada DJPb', NULL, NULL, NULL, '1. Tindak lanjut hasil monev menjadi bukti nyata peran advisory KPPN dalam membantu Pemda menyelesaikan kendala penyaluran dan meningkatkan kualitas laporan keuangan daerah.
2. hasil dan tindak lanjut monev mencerminkan akuntabilitas dan efektivitas pembinaan KPPN dalam mendukung kinerja fiskal daerah.', 13, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (176, 'Ketepatan Waktu Pengisian Volume Kerja dan Pelaporan Hasil Analisis Beban Kerja (ABK) kepada Sekretariat DJPb.', 'Penilaian dilakukan terhadap ketepatan waktu pengisian volume kerja dan pelaporan hasil Analisis Beban Kerja (ABK) kepada Sekretariat DJPb', 8, 43, NULL, 0, 'Ketepatan Waktu Pengisian Volume Kerja dan Pelaporan Hasil Analisis Beban Kerja (ABK) kepada Sekretariat DJPb.', NULL, NULL, NULL, '- Laporan ABK;
- Nota Dinas Penyampaian Laporan ABK.', 'PMK Nomor 238/PMK.01/2020 Tahun 2020 tentang Perubahan atas PMK Nomor 175/PMK.01/2016 tentang Pedoman Pelaksanaan Analisis Beban Kerja (Workload Analysis) di Lingkungan Kementerian Keuangan', NULL, NULL, NULL, '1. Analisis Beban Kerja digunakan untuk memastikan kesesuaian jumlah pegawai dengan kebutuhan organisasi.
2. Ketepatan waktu pelaporan menunjukkan kepatuhan terhadap tata kelola kepegawaian dan efektivitas manajemen SDM.', 6, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (164, 'FGD/Sharing Session terkait Special Mission', 'Berdasarkan penyelenggaraan atau keterlibatan KPPN dalam kegiatan FGD/Sharing Session bersama Pemerintah Daerah, Satuan Kerja, BLU/BLUD, dan/atau Masyarakat (UMKM) dengan materi yang meliputi namun tidak terbatas pada pemberdayaan UMKM; implementasi co-location; perencanaan keuangan BLU/BLUD; investasi daerah; dan/atau KPBU.', 7, 42, 26, 0, 'FGD/Sharing Session terkait Special Mission', NULL, NULL, NULL, '- Laporan pelaksanaan kegiatan; dan/atau
- Bukti keterlibatan kegiatan FGD/Sharing Session (misalnya ST/ Undangan, Daftar Hadir)', '1. Kepdirjen Nomor KEP-112/PB/2023 tentang Petunjuk Teknis Pemberdayaan UMKM Lingkup DJPb.
2. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
3. Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb.', NULL, NULL, NULL, '1. Kegiatan FGD/Sharing Session menjadi sarana advokasi fiskal dan komunikasi publik atas peran DJPb dalam mendorong ekonomi lokal dan mendukung misi pembangunan nasional.
2. Topik dapat disesuaikan dengan potensi daerah.', 14, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (165, 'Sosialisasi/ Bimtek terkait Local Government Advisory', 'Berdasarkan kegiatan sosialisasi/bimtek yang dilakukan oleh KPPN dengan materi kebijakan terkini terkait pengelolaan keuangan BLU/BLUD dan/atau pemberdayaan UMKM (dapat berkolaborasi dengan Kanwil DJPb setempat)', 7, 42, 26, 0, 'Sosialisasi/ Bimtek terkait Local Government Advisory', NULL, NULL, NULL, 'Laporan pelaksanaan kegiatan Sosialisasi/ Bimtek', '1. Kepdirjen Nomor KEP-112/PB/2023 tentang Petunjuk Teknis Pemberdayaan UMKM Lingkup DJPb.
2. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
3. Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb', NULL, NULL, NULL, '1. Fokus pembinaan diarahkan untuk memastikan kepatuhan terhadap ketentuan pengelolaan keuangan BLU, termasuk tata kelola kas, belanja, dan pelaporan.
2. Hasil monev digunakan untuk memberikan rekomendasi perbaikan pengelolaan keuangan BLU serta mendorong peningkatan kualitas layanan publik oleh BLU.', 15, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (170, 'Hasil dan Tindak Lanjut Monev terkait Special Mission', 'Berdasarkan pelaksanaan monitoring dan evaluasi kepada Pemda terkait Special Mission, KPPN menyusun dokumen hasil monev serta menindaklanjutinya dalam bentuk rekomendasi, solusi, dan/atau langkah perbaikan lainnya.', 7, 42, 27, 0, 'Hasil dan Tindak Lanjut Monev terkait Special Mission', NULL, NULL, NULL, 'laporan/bukti dukung kegiatan tindak lanjut monev terkait Special Mission', '1. Kepdirjen Nomor KEP-112/PB/2023 tentang Petunjuk Teknis Pemberdayaan UMKM Lingkup DJPb.
2. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
3. Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/ 2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb', NULL, NULL, NULL, '1. Peningkatan efektivitas terkait koordinasi KPPN dengan Pemda dalam mendukung program Special Mission.
2. Pelaporan hasil monev menjadi dasar perbaikan berkelanjutan (continuous improvement) dalam pelaksanaan Special Mission DJPb di daerah', 17, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (171, 'Perhitungan NKO', 'Penilaian dilakukan terhadap ketepatan dan kesesuaian perhitungan NKO KPPN berdasarkan pedoman Manajemen Kinerja di lingkungan Kementerian Keuangan.', 8, 43, NULL, 0, 'Perhitungan NKO', NULL, NULL, NULL, '- Laporan perhitungan NKO;
- Dokumen validasi atau hasil reviu Kanwil atas perhitungan NKO KPPN.', 'Keputusan Menteri Keuangan Republik Indonesia Nomor 300/KMK.01/2022 tentang Manajemen Kinerja di Lingkungan Kementerian Keuangan', NULL, NULL, NULL, '1. KPPN wajib memastikan keakuratan perhitungan NKO sebagai dasar penilaian kinerja organisasi dan pengambilan keputusan manajerial.
2. Ketepatan perhitungan NKO mencerminkan efektivitas sistem pengelolaan kinerja dan akuntabilitas hasil kinerja unit pelaksana.', 1, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (172, 'Kepatuhan Pengunggahan Dokumen Kinerja pada Aplikasi INTENSE', 'Penilaian dilakukan terhadap tingkat kepatuhan pegawai KPPN dalam mengunggah dokumen kinerja melalui Aplikasi INTENSE (menu monitoring kinerja Kanwil DJPb).', 8, 43, NULL, 0, 'Kepatuhan Pengunggahan Dokumen Kinerja pada Aplikasi INTENSE', NULL, NULL, NULL, '- Tangkapan layar atau rekapitulasi monitoring pengunggahan dokumen kinerja dari Aplikasi INTENSE;
- Daftar pegawai yang telah dan belum melakukan pengunggahan.', '1. Keputusan Menteri Keuangan Republik Indonesia Nomor 300/KMK.01/2022 tentang Manajemen Kinerja di Lingkungan Kementerian Keuangan.
2. Kepdirjen Perbendaharaan Nomor KEP-58/PB/2025 tentang Manajemen Kinerja di Lingkungan Direktorat Jenderal Perbendaharaan.', NULL, NULL, NULL, '1. Kepatuhan pengunggahan dokumen kinerja mencerminkan disiplin pegawai dan efektivitas pelaksanaan manajemen kinerja berbasis digital di KPPN.
2. KPPN wajib memastikan monitoring kinerja dilakukan secara berkala untuk menjamin akuntabilitas hasil kerja individu dan unit.', 2, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (173, 'Evaluasi Capaian Kinerja Internal', 'Penilaian dilakukan terhadap pelaksanaan evaluasi capaian kinerja internal KPPN yang dipimpin oleh Kepala KPPN dan didukung dokumentasi rapat serta laporan hasil evaluasi.', 8, 43, NULL, 0, 'Evaluasi Capaian Kinerja Internal', NULL, NULL, NULL, '- Notulen atau laporan hasil evaluasi capaian kinerja; dan/atau
- Bukti pelaksanaan rapat evaluasi kinerja bulanan/triwulanan.', '1. Keputusan Menteri Keuangan Republik Indonesia Nomor 300/KMK.01/2022 tentang Manajemen Kinerja di Lingkungan Kementerian Keuangan.
2. Kepdirjen Perbendaharaan Nomor KEP-58/PB/2025 tentang Manajemen Kinerja di Lingkungan Direktorat Jenderal Perbendaharaan.
', NULL, NULL, NULL, '1. Evaluasi rutin mencerminkan komitmen pimpinan dalam pengendalian kinerja dan perbaikan berkelanjutan.
2. Dokumentasi hasil evaluasi menjadi dasar analisis capaian dan tindak lanjut peningkatan kinerja organisasi.', 3, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (174, 'Penyusunan Dokumen Induk Sistem Manajemen Mutu ISO 9001:2015', 'Penilaian dilakukan terhadap kelengkapan dan kesesuaian Dokumen Induk SMM yang meliputi Pedoman Mutu, Konteks Organisasi, dan Kebijakan Mutu.', 8, 43, NULL, 0, 'Penyusunan Dokumen Induk Sistem Manajemen Mutu ISO 9001:2015', NULL, NULL, NULL, 'Dokumen Induk SMM (Pedoman Mutu, Konteks Organisasi, Kebijakan Mutu)', 'Kepdirjen Nomor KEP-151/PB/2018 tentang Pedoman Implementasi Sistem Manajemen Mutu ISO 9001:2015 pada KPPN', NULL, NULL, NULL, '1. Dokumen Induk SMM harus selalu diperbarui sesuai perubahan proses bisnis, struktur organisasi, atau konteks strategis KPPN.
2. Pemeliharaan dokumen mutu menjamin konsistensi penerapan SMM dan keselarasan dengan arah kebijakan DJPb.', 4, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (175, 'Pelaksanaan Pengujian Kepatuhan', 'Penilaian dilakukan terhadap pelaksanaan pengujian kepatuhan tahunan dan kelengkapan laporan hasil pengujian beserta dokumen pendukungnya', 8, 43, NULL, 0, 'Pelaksanaan Pengujian Kepatuhan', NULL, NULL, NULL, '- Laporan hasil pengujian kepatuhan;
- Surat Tugas, program kerja, dan dokumen pendukung pelaksanaan pengujian.', '', NULL, NULL, NULL, '1. Pengujian kepatuhan merupakan instrumen kontrol internal untuk memastikan penerapan SMM berjalan efektif dan sesuai ketentuan.
2. Laporan hasil pengujian digunakan sebagai dasar penyusunan tindakan korektif dan pencegahan.', 5, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (177, 'Pelaksanaan Standardisasi Kegiatan Manajemen KPPN', 'Penilaian dilakukan berdasarkan hasil evaluasi Aplikasi PETARAJA terhadap pelaksanaan Standar Kegiatan Manajemen (SKM) KPPN.', 8, 43, NULL, 0, 'Pelaksanaan Standardisasi Kegiatan Manajemen KPPN', NULL, NULL, NULL, 'Tangkapan layar nilai rata-rata SKM pada Aplikasi Petaraja', 'Nota Dinas Sekretaris Direktorat Jenderal Perbendaharaan Nomor ND-2168/PB.1/2025 hal Standardisasi Kegiatan Manajemen Instansi Vertikal DJPb', NULL, NULL, NULL, '1. Penilaian SKM mencerminkan tingkat kepatuhan KPPN terhadap standar kegiatan manajerial yang ditetapkan DJPb.
2. Hasil penilaian menjadi dasar penyusunan perbaikan tata kelola dan peningkatan kualitas manajemen internal.', 7, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (184, 'Kepatuhan Pembayaran Belanja Barang/Modal KPPN Selaku Satker', 'Penilaian dilakukan terhadap kebenaran, kepatuhan, dan kelengkapan dokumen pembayaran belanja barang dan/atau modal oleh KPPN selaku satker.', 8, 45, NULL, 0, 'Kepatuhan Pembayaran Belanja Barang/Modal KPPN Selaku Satker', NULL, NULL, NULL, '- Dokumen pembayaran SPM/SP2D.
- Berkas pendukung belanja (kontrak, kuitansi, berita acara, SSP, faktur pajak, dan bukti pengujian).', '1. PMK Nomor 171/PMK.05/2021 tentang Pelaksanaan Sistem SAKTI.
2. PMK Nomor 107 Tahun 2024 tentang Perubahan Atas Peraturan Menteri Keuangan Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran Serta Akuntansi dan Pelaporan Keuangan.
3. Kepdirjen Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN.', NULL, NULL, NULL, '1. KPPN wajib memastikan seluruh proses pembayaran belanja barang dan modal telah melalui pengujian SPM sesuai ketentuan.
2. KPPN wajib memastikan penyelesaian tagihan kontraktual telah tepat waktu.
3. Kelengkapan dan kebenaran dokumen (kontrak, berita acara, kuitansi, bukti setoran pajak, dan lainnya) menjadi indikator kepatuhan pengelolaan keuangan KPPN satker pengelola APBN.', 14, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (178, 'Penyelesaian Layanan dan Administrasi Kepegawaian yang sesuai Prosedur', 'Penilaian dilakukan terhadap kesesuaian pelaksanaan layanan dan administrasi kepegawaian (cuti, karpeg/karis/karsu, kenaikan pangkat, dan lainnya) dengan ketentuan dan prosedur yang berlaku berdasarkan hasil uji sampling.', 8, 44, NULL, 0, 'Penyelesaian Layanan dan Administrasi Kepegawaian yang sesuai Prosedur', NULL, NULL, NULL, 'Sampling dokumen layanan kepegawaian.', '1. Peraturan Pemerintah Nomor 5 Tahun 2024 tentang Perubahan Kesembilan Belas Atas Peraturan Pemerintah Nomor 7 Tahun 1977 Tentang Peraturan Gaji Pegawai Negeri Sipil
2. Peraturan Kepala Badan Kepegawaian Negara Nomor 3 Tahun 2020 tentang Petunjuk Teknis Pemberhentian Pegawai Negeri Sipil
3. Keputusan Kepala BKN Nomor 12 Tahun 2002 Tentang Ketentuan Pelaksanaan Peraturan Pemerintah Nomor 99 Tahun 2000 Tentang Kenaikan Pangkat Pegawai Negeri Sipil Sebagaimana Telah Diubah Dengan Peraturan Pemerintah Nomor 12 Tahun 2002
4. Surat Edaran Menteri Keuangan Nomor SE-15/MK.1/2018 tentang Pelaksanaan Cuti PNS di Lingkungan Kementerian Keuangan
5. Surat Edaran Kepala Badan Kepegawaian Negara Nomor 16 Tahun 2022 tentang Kartu Aparatur Sipil Negara
6. Surat Edaran Kepala Badan Kepegawaian Negara Nomor 13 Tahun 2024 tentang Kartu Istri/Kartu Suami Aparatur Sipil Negara Virtual
7. Nota Dinas Sekretaris Ditjen Perbendaharaan Nomor ND 1011/PB.1/2022 hal Peningkatan Akurasi Data Sumber Daya Manusia pada Aplikasi Human Resources Information System di Lingkungan Direktorat Jenderal Perbendaharaan', NULL, NULL, NULL, '1. KPPN wajib memastikan seluruh layanan kepegawaian dilaksanakan sesuai ketentuan dan SOP administrasi kepegawaian.
2. Kesalahan prosedur menunjukkan lemahnya pengendalian mutu layanan internal yang harus segera diperbaiki.
3. Ketepatan dan kepatuhan prosedural mencerminkan kualitas tata kelola SDM di lingkungan KPPN.', 8, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (179, 'Digitalisasi Dokumen Kepegawaian', 'Penilaian dilakukan terhadap tingkat kelengkapan dokumen kepegawaian pegawai KPPN yang diunggah pada Aplikasi PBN Open dan HRIS/Satu Kemenkeu.', 8, 44, NULL, 0, 'Digitalisasi Dokumen Kepegawaian', NULL, NULL, NULL, '- Tangkapan layar hasil monitoring kelengkapan dokumen pada Aplikasi PBN Open;
- Daftar rekapitulasi status kelengkapan dokumen kepegawaian', '1. Surat Sekretaris Direktorat Jenderal Perbendaharaan Nomor S 6596/PB.1/2012 hal Updating Data Kepegawaian
2. Surat Edaran Menteri Keuangan Nomor SE-20/MK.1/2019 tentang Pelaksanaan Pemeliharaan Data SDM pada Human Resources Information System (HRIS) bagi Seluruh Pegawai di Lingkungan Kementerian Keuangan', NULL, NULL, NULL, '1. Digitalisasi dokumen kepegawaian mendukung transparansi dan efisiensi pengelolaan SDM.
2. KPPN wajib memastikan setiap pegawai memiliki data kepegawaian yang lengkap dan mutakhir di sistem.
3. Kelengkapan dokumen menjadi dasar validasi hak kepegawaian serta mendukung penilaian kinerja yang objektif.', 9, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (180, 'Tingkat Standar Kompetensi Mansoskul Pegawai', 'Penilaian dilakukan terhadap tingkat pemenuhan standar kompetensi pejabat dan pegawai KPPN berdasarkan data pada Aplikasi HRIS', 8, 44, NULL, 0, 'Tingkat Standar Kompetensi Mansoskul Pegawai', NULL, NULL, NULL, '- Tangkapan layar hasil monitoring kelengkapan dokumen pada Aplikasi PBN Open;
- Daftar rekapitulasi status kelengkapan dokumen kepegawaian
- Laporan JPM Pejabat dan Pegawai KPPN Menjadi: Laporan Hasil Assessment Center (LHAC) Pejabat dan Pegawai KPPN
- Hasil analisis kesenjangan (gap analysis) kompetensi jabatan pada Aplikasi PbnOpen ', '1. Peraturan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Nomor 38 Tahun 2017.
2. Keputusan Menteri Keuangan Nomor 504.1/KMK.01/2021 tentang Pengelolaan Penilaian Kompetensi Manajerial dan Sosial Kultural di Lingkungan Kementerian Keuangan', NULL, NULL, NULL, '1. Pemenuhan standar kompetensi menunjukkan kesiapan dan profesionalisme pegawai dalam menjalankan fungsi perbendaharaan.
2. KPPN wajib melakukan pembinaan berkelanjutan terhadap kompetensi pegawai yang belum memenuhi standar berdasarkan hasil pemetaan kompetensi yang dilakukan oleh Bagian SDM Sekretariat Ditjen Perbendaharaan.
3. Tingkat kompetensi menjadi indikator utama efektivitas pengelolaan SDM dan kinerja unit.', 10, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (181, 'Pemenuhan Data Evaluasi Kinerja Anggaran KPPN Selaku Satker', 'Penilaian dilakukan terhadap kelengkapan dan ketepatan waktu pengisian data evaluasi kinerja anggaran KPPN sebagai satker pada Aplikasi SMART DJA', 8, 45, NULL, 0, 'Pemenuhan Data Evaluasi Kinerja Anggaran KPPN Selaku Satker', NULL, NULL, NULL, 'Tangkapan layar Aplikasi SMART DJA yang menunjukkan data terisi per bulan', 'PMK No. 107 Tahun 2024 tentang Perubahan Atas Peraturan Menteri Keuangan Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran Serta Akuntansi dan Pelaporan Keuangan', NULL, NULL, NULL, '1. Pengisian data pada SMART DJA merupakan kewajiban satker sebagai bagian dari sistem monitoring dan evaluasi kinerja anggaran nasional.
2. KPPN wajib memastikan konsistensi, akurasi, dan ketepatan waktu pengisian sebagai dasar pengambilan kebijakan berbasis data oleh DJA dan DJPb.', 11, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (197, 'Keterlibatan KPPN dalam Penguatan Brand Image DJPb di Wilayah Kerja', 'Penilaian dilakukan terhadap partisipasi aktif KPPN dalam kegiatan sosial, edukatif, kemasyarakatan, atau publikasi yang memperkuat citra positif Direktorat Jenderal Perbendaharaan (DJPb) di wilayah kerja.', 8, 48, NULL, 0, 'Keterlibatan KPPN dalam Penguatan Brand Image DJPb di Wilayah Kerja', NULL, NULL, NULL, '- Dokumentasi kegiatan sosial, edukatif, atau publikasi media terkait.
- Bukti publikasi (artikel, unggahan media sosial, atau pemberitaan lokal', '', NULL, NULL, NULL, '1. KPPN berperan sebagai representasi DJPb di daerah melalui kegiatan sosial, edukasi publik, atau publikasi yang meningkatkan kepercayaan masyarakat terhadap pengelolaan APBN.
2. Kegiatan dapat berupa partisipasi dalam edukasi fiskal, literasi keuangan, aksi sosial, atau publikasi yang menonjolkan nilai-nilai Kemenkeu Satu dan semangat Treasury.
3. Keterlibatan ini menunjukkan kontribusi nyata KPPN dalam membangun citra DJPb sebagai institusi yang transparan, inklusif, dan melayani.', 27, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (182, 'Pengisian Data Evaluasi Anggaran KPPN sebagai Satker pada Aplikasi
e-Monev Bappenas', 'Penilaian dilakukan terhadap keterisian data pelaksanaan anggaran dan capaian output KPPN pada Aplikasi e-Monev Bappenas secara periodik setiap bulan', 8, 45, NULL, 0, 'Pengisian Data Evaluasi Anggaran KPPN sebagai Satker pada Aplikasi
e-Monev Bappenas', NULL, NULL, NULL, 'Bukti pengisian data pada Aplikasi e-Monev Bappenas', '1. Peraturan Menteri Negara Perencanaan Pembangunan Nasional/Kepala Badan Perencanaan Pembangunan Nasional Nomor 1 Tahun 2023 tentang Tata Cara Pemantauan, Pengendalian dan Evaluasi Pelaksanaan Rencana Pembangunan.
2. PMK No. 107 Tahun 2024 tentang Perubahan Atas Peraturan Menteri Keuangan Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran Serta Akuntansi dan Pelaporan Keuangan.', NULL, NULL, NULL, '1. KPPN wajib melakukan pelaporan e-Monev Bappenas secara tepat waktu sebagai bentuk akuntabilitas kinerja pelaksanaan anggaran.
2. Data e-Monev digunakan sebagai instrumen evaluasi kinerja program pemerintah dan indikator capaian output kegiatan.', 12, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (183, 'Kebenaran pembayaran Uang Makan dan Uang Lembur', 'Penilaian dilakukan terhadap kepatuhan KPPN sebagai satker dalam pembayaran Uang Makan (UM) dan Uang Lembur (UL), termasuk kelengkapan dan kebenaran dokumen pendukung', 8, 45, NULL, 0, 'Kebenaran pembayaran Uang Makan dan Uang Lembur', NULL, NULL, NULL, 'Dokumen pembayaran UM dan UL (SPM, SP2D, daftar hadir, Surat Perintah Kerja Lembur (SPKL), Surat Pernyataan Tanggungjawab Perintah Lembur (SPTPL), dan perhitungan pembayaran lembur)', '1. PMK Nomor 72/PMK.05/2016 tentang Uang Makan Bagi Pegawai Aparatur Sipil Negara.
2. PMK Nomor 182/PMK.05/2022 Tahun 2022 tentang Piloting Pembayaran dalam rangka Pelaksanaan Anggaran Pendapatan dan Belanja Negara melalui Platform Pembayaran Pemerintah.
3. PMK No. 107 Tahun 2024 tentang Perubahan Atas Peraturan Menteri Keuangan Nomor 62 Tahun 2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran Serta Akuntansi dan Pelaporan Keuangan.', NULL, NULL, NULL, '1. KPPN wajib memastikan perhitungan dan pembayaran UM serta UL telah sesuai ketentuan tarif dan ketentuan perbendaharaan yang berlaku.
2. Dokumen pendukung (daftar hadir, surat perintah lembur, dan rekap jam kerja) harus lengkap dan sah untuk menjamin akuntabilitas belanja pegawai', 13, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (185, 'Kepatuhan Pelaksanaan Perikatan oleh PPK', 'Penilaian dilakukan terhadap kesesuaian pelaksanaan perikatan oleh PPK dengan ketentuan peraturan pengadaan barang/jasa pemerintah.', 8, 46, NULL, 0, 'Kepatuhan Pelaksanaan Perikatan oleh PPK', NULL, NULL, NULL, '- Dokumen kontrak perikatan oleh PPK;
- Berita acara hasil pemeriksaan atau evaluasi dokumen pengadaan', '1. Peraturan Presiden Nomor 16 Tahun 2018 tentang Pengadaan Barang/Jasa Pemerintah sebagaimana telah diubah terakhir dengan Peraturan Presiden Nomor 46 Tahun 2025.
2. Peraturan LKPP Nomor 12 Tahun 2021 tentang Pedoman Pelaksanaan Pengadaan Barang/Jasa Pemerintah melalui Penyedia', NULL, NULL, NULL, '1. KPPN wajib memastikan setiap perikatan dilaksanakan sesuai ketentuan Perpres Pengadaan Barang/Jasa Pemerintah, termasuk pemenuhan dokumen perencanaan, spesifikasi, dan kontrak.
2. Kepatuhan terhadap prosedur perikatan menunjukkan tata kelola pengadaan yang transparan, efisien, dan akuntabel.', 15, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (186, 'Kepatuhan Pelaksanaan Perikatan oleh PPK
Digitalisasi Dokumen Pencairan Anggaran KPPN selaku Satker', 'Penilaian dilakukan terhadap tingkat digitalisasi dokumen pencairan anggaran, baik dokumen komitmen maupun penyelesaian tagihan oleh KPPN selaku satker.', 8, 46, NULL, 0, 'Kepatuhan Pelaksanaan Perikatan oleh PPK
Digitalisasi Dokumen Pencairan Anggaran KPPN selaku Satker', NULL, NULL, NULL, '- Tangkapan layar arsip digital dokumen pencairan anggaran;
- Daftar inventaris arsip elektronik KPPN', '1. PMK Nomor 164/PMK.01/2021 tentang Pedoman Tata Naskah Dinas di Lingkungan Kementerian Keuangan.
2. Surat Edaran Direktur Jenderal Perbendaharaan Nomor SE-35/PB/2021 tentang Implementasi Tata Naskah Dinas Elektronik di Lingkungan DJPb', NULL, NULL, NULL, '1. KPPN wajib melakukan digitalisasi dokumen untuk mendukung efisiensi, kemudahan akses, dan keamanan arsip keuangan.
2. Arsip digital menjadi dasar pengendalian intern dan pembuktian administrasi dalam audit atau rekonsiliasi data keuangan', 16, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (187, 'Pengamanan dan Pemeliharaan BMN', 'Penilaian dilakukan terhadap pelaksanaan kegiatan pengamanan dan pemeliharaan BMN sesuai pedoman yang berlaku di lingkungan Kementerian Keuangan.', 8, 46, NULL, 0, 'Pengamanan dan Pemeliharaan BMN', NULL, NULL, NULL, 'Dokumen laporan pengamanan dan pemeliharaan BMN', '1. PMK Nomor 153/PMK.06/2021 tentang Perencanaan Kebutuhan BMN
2. PMK Nomor 40 Tahun 2024 tentang Tata Cara Penggunaan Barang Milik Negara.
3. PMK Nomor 120 Tahun 2024 tentang 
Tata Cara Pengelolaan Barang Milik Negara yang Tidak Digunakan untuk Penyelenggaraan Tugas dan Fungsi Kementerian/ Lembaga', NULL, NULL, NULL, '1. Pengamanan dan pemeliharaan BMN wajib dilakukan secara berkala untuk menjaga keutuhan, keberfungsian, dan nilai aset negara.
2. KPPN memastikan adanya dokumentasi kegiatan pemeliharaan dan laporan pengamanan sesuai standar pengelolaan BMN.', 17, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (188, 'Kesesuaian dengan Standarisasi Sarana Prasarana Kendaraan dan Peralatan', 'Penilaian dilakukan terhadap tingkat kesesuaian sarana dan prasarana KPPN dengan standardisasi kebutuhan jumlah, spesifikasi dan usia dan tidak terdapat aset yang berlebih baik yang digunakan/tidak digunakan (pengecualian aset berlebih tsb dalam kondisi rusak berat dan dalam proses penghapusan) dengan formula perhitungan:

((bobot Σ eksisting )/(standard Σ ))  +  ((rerata bobot spek)/(standard spek))  + ((rerata bobot usia)/(standard usia))', 8, 46, NULL, 0, 'Kesesuaian dengan Standarisasi Sarana Prasarana Kendaraan dan Peralatan', NULL, NULL, NULL, 'Kertas kerja kesesuaian sarpras', '1. Peraturan Menteri Keuangan Nomor 138 Tahun 2024 tentang Standar Barang dan Standar Kebutuhan Barang Milik Negara.
2. Keputusan Menteri Keuangan Nomor KMK 334/KMK.01/2021 tentang Pengelolaan Barang Milik Negara di Lingkungan Kementerian Keuangan.
3. Surat Edaran Direktur Jenderal Perbendaharaan Nomor SE-46/PB/2022 tentang Standardisasi Kebutuhan dan Masa Manfaat Peralatan dan Mesin Serta Standardisasi Luas Ruangan pada Instansi Vertikal DJPb.', NULL, NULL, NULL, '1. KPPN wajib menjaga kondisi sarana dan prasarana sesuai standardisasi yang dapat mempengaruhi efektifitas pelaksnaan tusi.
2. Pemenuhan standar mendukung kenyamanan kerja, pelayanan prima, dan kesiapan pelaksanaan tugas operasional.
3. Ketertiban dalam menjaga keseimbangan siklus logistik aset khususnya antara perencanaan, pengadaan dan penghapusan
4. Meminimalisasi potensi temuan akibat aset yang melebihi standard (digunakan/tidak digunakan) namun tetap dicover biaya pemeliharaanya
5. Mengukur upaya proaktif dalam pemenuhan defisit ataupun penanganan aset berlebih', 18, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (189, 'Kesesuaian dengan Standarisasi Sarana Prasarana Ruang Kerja', 'Penilaian dilakukan terhadap tingkat kesesuaian ketersediaan jenis dan luasan ruang dibandingkan standard dengan formula perhitungan

(Σ ruang )/(standard Σ ruang )  +  (rerata luas ruang)/(standard luas ruang)+optimalisasi/(luas underutilize)', 8, 46, NULL, 0, 'Kesesuaian dengan Standarisasi Sarana Prasarana Ruang Kerja', NULL, NULL, NULL, 'Kertas kerja kesesuaian standar sarpras ruang kerja ', '1. Kepdirjen Perbendaharaan Nomor KEP 97/PB/2021 tentang Buku Pedoman Standar Layout dan Desain Bangunan Instansi Vertikal DJPb.
2. Surat Edaran Direktur Jenderal Perbendaharaan Nomor SE-46/PB/2022 tentang Standardisasi Kebutuhan dan Masa Manfaat Peralatan dan Mesin Serta Standardisasi Luas Ruangan pada Instansi Vertikal DJPb.', NULL, NULL, NULL, '1. KPPN wajib menjaga kondisi sarana dan prasarana sesuai standardisasi yang dapat mempengaruhi efektifitas pelaksnaan tusi.
2. Pemenuhan standar mendukung kenyamanan kerja, pelayanan prima, dan kesiapan pelaksanaan tugas operasional.
3. Penyediaan ruang kerja sesuai standard apabila terdapat kelebihan luasan (underutilize) upaya optimalisasi apa yang sudah ditempuh', 19, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (190, 'Kesesuaian dengan Standarisasi Sarana Prasarana Tempat Hunian Pegawai (Rumah/
Mess)', 'Penilaian dilakukan terhadap tingkat kesesuaian jumlah dan peruntukan penghunian dengan formula perhitungan

Ketika jumlah tempat hunian < standard

(Σ hunian )/(standard )-  (Σ penghuni tidak berhak)/(Σ hunian)  X 100

Ketika jumlah tempat hunian > standard

(Σ hunian )/(standard )-  (Σ penghuni tidak berhak)/(Σ hunian)  X 100', 8, 46, NULL, 0, 'Kesesuaian dengan Standarisasi Sarana Prasarana Tempat Hunian Pegawai (Rumah/
Mess)', NULL, NULL, NULL, 'Kertas kerja kesesuaian standar sarpras tempat hunian pegawai', '1. Peraturan Menteri Keuangan Nomor 138 Tahun 2024 tentang Standar Barang dan Standar Kebutuhan Barang Milik Negara.
2. Keputusan Menteri Keuangan Nomor KMK 334/KMK.01/2021 tentang Pengelolaan Barang Milik Negara di Lingkungan Kementerian Keuangan.', NULL, NULL, NULL, '1. KPPN wajib menjaga kondisi sarana dan prasarana sesuai standardisasi yang dapat mempengaruhi efektifitas pelaksnaan tusi.
2. Pemenuhan standar mendukung kenyamanan kerja, pelayanan prima, dan kesiapan pelaksanaan tugas operasional.
3. Penyediaan hunian bagi pegawai harus diiringi dengan upaya penertiban bila dihuni oleh pihak tidak berhak ataupun optimalisasi penggunaan bersama dengan UE-1 lain bila jumlah berlebih', 20, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (191, 'Validitas Data SIMKA', 'Penilaian dilakukan terhadap kesesuaian data dengan kondisi aktual di lapangan dengan formula perhitungan

(Σ gedung+ Σ rumah+ Σ kendaraan+ Σ peralatan)/(data valid dan aktual )  X 100', 8, 46, NULL, 0, 'Validitas Data SIMKA', NULL, NULL, NULL, '- Kertas kerja validasi
- Surat pernyataan validitas data tingkat pembina eselon III (KPPN) yang divalidasi oleh tingkat Pembina eselon II (Kanwil)', '1. Peraturan Menteri Keuangan Nomor 138 Tahun 2024 tentang Standar Barang dan Standar Kebutuhan Barang Milik Negara.
2. Keputusan Menteri Keuangan Nomor KMK 334/KMK.01/2021 tentang Pengelolaan Barang Milik Negara di Lingkungan Kementerian Keuangan.
3. Surat Edaran Direktur Jenderal Perbendaharaan Nomor SE-46/PB/2022 tentang Standardisasi Kebutuhan dan Masa Manfaat Peralatan dan Mesin Serta Standardisasi Luas Ruangan pada Instansi Vertikal DJPb.', NULL, NULL, NULL, '1. Data SIMKA sebagai basis data penyusunan roadmap kebutuhan dan RKBMN yang validitasnya akan berpengaruh langsung terhadap pemenuhan kebutuhan sarpras
2. Fungsi dan tujuan data SIMKA bersifat manjerial, berbeda dengan aplikasi aset lainnya yang bersifat pendukung operasional dan proses bisnis serta pelaporan', 21, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (192, 'Pengelolaan Manajemen Risiko', 'Penilaian dilakukan terhadap pelaksanaan identifikasi, pemantauan, dan evaluasi risiko yang dilakukan oleh KPPN serta penyampaian laporan triwulanan.', 8, 47, NULL, 0, 'Pengelolaan Manajemen Risiko', NULL, NULL, NULL, 'Laporan pelaksanaan identifikasi, pemantauan, dan evaluasi risiko yang dilakukan oleh KPPN periode triwulanan', '1. PMK Nomor 222/PMK.01/2021 Tahun 2021 tentang Manajemen Risiko Pengelolaan Keuangan Negara.
2. KMK Nomor 105/KMK.01/2022 tentang Petunjuk Pelaksanaan Manajemen Risiko Pengelolaan Keuangan Negara.
3. Kepdirjen Perbendaharaan Nomor KEP-252/PB/2022 tantang Petunjuk Teknis Pelaksanaan Manajemen Risiko Pengelolaan Keuangan Negara untuk Risiko Organisasi di Lingkungan Direktorat Jenderal Perbendaharaan', NULL, NULL, NULL, '1. KPPN wajib mengidentifikasi dan mengevaluasi risiko secara berkala untuk meminimalkan potensi gangguan terhadap pencapaian tujuan organisasi.
2. Pelaporan manajemen risiko menjadi dasar pengambilan keputusan dan pembinaan mitigasi risiko oleh Kanwil DJPb', 22, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (193, 'Tindak lanjut atas Temuan Aparat Pemeriksa (BPK, Itjen, dll)', 'Penilaian dilakukan terhadap hasil pemeriksaan oleh aparat pengawasan internal dan eksternal (BPK, Itjen, atau lembaga pemeriksa lainnya) serta tindak lanjut yang dilakukan oleh KPPN.', 8, 47, NULL, 0, 'Tindak lanjut atas Temuan Aparat Pemeriksa (BPK, Itjen, dll)', NULL, NULL, NULL, 'Laporan tindak lanjut temuan pemeriksaan (apabila ada).', 'PMK Nomor 124 Tahun 2024 tentang Organisasi dan Tata Kerja Kementerian Keuangan', NULL, NULL, NULL, '1. KPPN wajib menindaklanjuti seluruh temuan hasil pemeriksaan secara tepat waktu dan terdokumentasi.
2. Ketaatan pada rekomendasi pemeriksa menunjukkan komitmen terhadap akuntabilitas, transparansi, dan perbaikan tata kelola.', 23, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (194, 'Pengelolaan Pengaduan', 'Penilaian dilakukan terhadap pengelolaan pengaduan masyarakat melalui kanal resmi (email, kotak pengaduan, LAPOR!, atau kanal lainnya) serta tindak lanjut yang dilakukan KPPN.', 8, 47, NULL, 0, 'Pengelolaan Pengaduan', NULL, NULL, NULL, '- SK Petugas Pengelola Pengaduan;
- SOP/ Mekanisme penanganan pengaduan;', '1. PMK Nomor 205/PMK.09/2022 tentang Pengelolaan Pelaporan Pelanggaran dan Perlindungan Pelapor di Lingkungan Kementerian Keuangan.
2. Perdirjen Perbendaharaan Nomor PER-3/PB/2013 tentang Pengelolaan Pengaduan di Lingkungan DJPb.
3. Kepdirjen Nomor KEP-57/PB/2023 tentang Standar Pelayanan DJPB
4. Kepdirjen Nomor KEP-116/PB/PB.1/2024 tentang Perubahan atas Kepdirjen Nomor KEP-244/PB/PB.1/2023 tentang Standar Operasional Prosedur pada KPPN', NULL, NULL, NULL, 'KPPN wajib menetapkan petugas dan mekanisme pengelolaan pengaduan secara formal serta memastikan seluruh kanal pengaduan berfungsi aktif', 24, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (195, 'Upaya Tindak Lanjut Pengaduan', 'Penilaian dilakukan terhadap tindak lanjut atas pengaduan masyarakat yang diterima melalui kanal resmi KPPN seperti email, aplikasi LAPOR!, kotak pengaduan, atau kanal resmi lainnya.', 8, 47, NULL, 0, 'Upaya Tindak Lanjut Pengaduan', NULL, NULL, NULL, '- Laporan rekapitulasi tindak lanjut pengaduan;
- Bukti penyelesaian pengaduan (BA, surat balasan, atau tanggapan pada sistem).', '', NULL, NULL, NULL, '1. KPPN wajib memastikan setiap pengaduan ditangani sesuai prosedur dan ditindaklanjuti hingga tuntas dengan hasil yang terdokumentasi.
2. Ketepatan waktu dan kualitas tindak lanjut pengaduan menjadi cerminan responsivitas serta integritas layanan publik.
3. Pelaporan hasil tindak lanjut harus terintegrasi dengan sistem pemantauan pengaduan di lingkungan Kementerian Keuangan', 25, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (196, 'Pembaharuan Konten pada Website dan Media Sosial KPPN', 'Penilaian dilakukan terhadap konsistensi dan frekuensi pembaruan konten pada kanal resmi KPPN, baik website maupun media sosial, sesuai standar keterbukaan informasi publik di lingkungan Kementerian Keuangan.', 8, 48, NULL, 0, 'Pembaharuan Konten pada Website dan Media Sosial KPPN', NULL, NULL, NULL, '- Tangkapan layar pembaruan konten website/ media sosial per bulan;
- Jadwal unggahan konten dan dokumentasi publikasi informasi', '1. Peraturan Menteri Keuangan PMK Nomor 60/PMK.01/2022 tentang Perubahan atas PMK Nomor 83/PMK.01/2018 tentang Pejabat Pengelola Informasi dan Dokumentasi di Lingkungan Kementerian Keuangan.
2. PMK Nomor 133/PMK.01/2022 tentang Tata Kelola Teknologi Informasi dan Komunikasi di Lingkungan Kemenkeu.
3. KMK Nomor 222 Tahun 2023 tentang Pedoman Pengelolaan Komunikasi Kementerian Keuangan.
4. Perdirjen Perbendaharaan Nomor PER-1/PB/2021 tentang Kebijakan Sistem Manajemen Keamanan Informasi di Lingkungan DJPb.', NULL, NULL, NULL, '1. KPPN wajib memperbarui konten website dan media sosial secara berkala dengan informasi yang akurat, relevan, dan bernilai publik.
2. Pembaruan mencakup publikasi berita, edukasi fiskal, layanan, dan informasi kegiatan KPPN yang mendukung transparansi dan akuntabilitas.
3. Frekuensi dan kualitas pembaruan mencerminkan komitmen KPPN terhadap prinsip keterbukaan informasi publik dan layanan prima kepada masyarakat.', 26, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (198, 'Pelaksanaan Efektivitas Employee Advocacy', 'Penilaian dilakukan terhadap partisipasi aktif pegawai KPPN melalui media sosial masing-masing terhadap amplifikasi untuk mendukung amplifikasi konten Kementerian Keuangan sebagai bagian dari employee engagement melalui penghitungan tingkat jumlah pegawai yang berpartisipasi sesuai topik proaktif agenda setting yang ditetapkan.', 8, 48, NULL, 0, 'Pelaksanaan Efektivitas Employee Advocacy', NULL, NULL, NULL, 'Tingkat partisipasi aktif  pegawai dalam program employee advocacy', '1. KMK Nomor 222 Tahun 2023 tentang Pedoman Pengelolaan Komunikasi Kementerian Keuangan.
2. Surat Edaran Menteri Keuangan Nomor SE-16/MK.01/2018 tentang Panduan Aktivitas dan Penggunaan Media Sosial Bagi Pegawai Kementerian Keuangan RI.', NULL, NULL, NULL, '1. KPPN selaku Kuasa BUN di daerah perlu menyampaikan informasi terkait kebijakan, tujuan dan program pengelolaan APBN kepada masyarakat luas melalui kampanye komunikasi yang efektif, tepat sasaran dan berdampak terhadap peningkatan pengetahuan, dukungan, dan partisipasi publik. 
2. Komunikasi publik dilakukan juga agar dapat memberi dampak positif dan tepat sasaran sehingga peningkatan dukungan publik terhadap kebijakan di bidang keuangan negara mendapatkan kepercayaan dan dukungan publik.', 28, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (199, 'Penyusunan dan Pelaporan Inovasi KPPN', 'Penilaian dilakukan terhadap proses penetapan dan pelaporan inovasi di lingkungan KPPN, meliputi SK Inovasi, proposal inovasi, serta pendaftaran inovasi pada Katalog Inovasi Satu Kemenkeu', 8, 49, NULL, 0, 'Penyusunan dan Pelaporan Inovasi KPPN', NULL, NULL, NULL, '- SK Penetapan Inovasi dan proposal inovasi tahun berjalan;
- Bukti pendaftaran inovasi pada Katalog Inovasi Satu Kemenkeu (ND ke Setditjen Perbendaharaan).', 'Keputusan Menteri Keuangan Nomor 1005/KM.1/2022 tentang Pedoman Pengelolaan Inovasi di Lingkungan Kementerian Keuangan, perlu menetapkan Keputusan Sekretaris Jenderal tentang Pedoman Pengelolaan Ide Inovasi di Lingkungan Sekretariat Jenderal', NULL, NULL, NULL, '1. Penetapan inovasi disertai proposal menjadi bentuk komitmen KPPN dalam mendukung budaya inovatif dan continuous improvement.
2. Pendaftaran inovasi pada Katalog Inovasi Satu Kemenkeu memastikan validasi dan keterpaduan inovasi di lingkungan Kemenkeu.
3. Inovasi wajib terdokumentasi dan dilaporkan secara formal melalui kanal resmi untuk menjamin akuntabilitas dan keberlanjutan.', 29, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (200, 'Keberlanjutan Inovasi', 'Penilaian dilakukan terhadap pengelolaan inovasi KPPN yang meliputi pemanfaatan, evaluasi, dan pengembangan inovasi yang telah ditetapkan.', 8, 49, NULL, 0, 'Keberlanjutan Inovasi', NULL, NULL, NULL, '- Laporan evaluasi dan pengembangan inovasi;
-Dokumentasi hasil pemanfaatan atau pengukuran dampak inovasi.', '', NULL, NULL, NULL, '1. Keberlanjutan inovasi menjamin efektivitas inovasi.
2. Evaluasi dan pengembangan inovasi wajib dilaksanakan secara periodik untuk memastikan inovasi tetap relevan dan memberi dampak nyata.
3. Pengelolaan inovasi menjadi bukti konsistensi KPPN dalam mendukung tata kelola berkinerja tinggi berbasis inovasi.', 30, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (201, 'Keberman-faatan Inovasi /Direplikasi Pihak Lain', 'Penilaian dilakukan terhadap sejauh mana inovasi KPPN memberi manfaat luas dan diadopsi atau direplikasi oleh pihak eksternal.', 8, 49, NULL, 0, 'Keberman-faatan Inovasi /Direplikasi Pihak Lain', NULL, NULL, NULL, '- Laporan evaluasi dan pengembangan inovasi;
- Dokumentasi hasil pemanfaatan atau pengukuran dampak inovasi.
- Bukti sosialisasi/promosi inovasi (laporan kegiatan, publikasi, atau berita media);
- Surat keterangan/referensi pihak lain atas replikasi inovasi.', '', NULL, NULL, NULL, '1. Kebermanfaatan inovasi diukur dari sejauh mana inovasi memberi nilai tambah dan mampu diadopsi oleh pihak lain (internal DJPb maupun instansi eksternal).
2.Sosialisasi inovasi menunjukkan peran aktif KPPN dalam membangun knowledge sharing ecosystem di lingkungan Kemenkeu.
3. Replikasi inovasi memperluas dampak positif dan memperkuat posisi KPPN sebagai pelopor praktik baik (best practice).', 31, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (202, 'Mempertahan-kan Prestasi atau Meningkatkan Capaian Prestasi dengan Prestasi Baru', 'Penilaian dilakukan terhadap capaian prestasi KPPN baik dalam mempertahankan prestasi sebelumnya maupun memperoleh prestasi baru pada tahun berjalan.', 8, 49, NULL, 0, 'Mempertahan-kan Prestasi atau Meningkatkan Capaian Prestasi dengan Prestasi Baru', NULL, NULL, NULL, '- Sertifikat penghargaan, naskah dinas, atau dokumen pengakuan prestasi.
- Rekapitulasi capaian prestasi periode sebelumnya dan tahun berjalan.', 'KMK Nomor 300/KMK.01/2022 tentang Manajemen Kinerja di Lingkungan Kementerian Keuangan

', NULL, NULL, NULL, '1. Prestasi menjadi refleksi dari hasil kinerja unggul, inovasi berkelanjutan, dan kolaborasi tim yang efektif di lingkungan KPPN.
2. KPPN perlu mengintegrasikan capaian prestasi ke dalam sistem manajemen kinerja sebagai bentuk penguatan motivasi dan budaya kompetitif positif.
3. Pemeliharaan prestasi menunjukkan konsistensi KPPN dalam mewujudkan Treasury Excellence.', 32, NULL);
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (120, 'Akurasi Rencana Penarikan Dana (RPD) Harian Satker secara semesteran', 'Penilaian berdasarkan tingkat deviasi RPD pada aplikasi MyIntress Modul Renkas, dengan formula: Nilai Deviasi = (30% x Deviasi Unit) (70% x Deviasi Nilai)', 5, 25, NULL, 0, '', NULL, NULL, NULL, 'Tangkapan layar Myintress terkait monitoring deviasi RPD', '1.	PMK Nomor 155 Tahun 2023 tentang Perencanaan Kas Pemerintah Pusat.
2.	Perdirjen Perberdaharaan Nomor PER-5/PB/2024 tentang Petunjuk Teknis Penilaian Indikator Kinerja Pelaksanaan Anggaran Belanja Kementerian Negara/ Lembaga.
3.	Peraturan/ketentuan lainnya terkait rencana penarikan dana, rencana penerimaan dana, dan perencanaan kas.', NULL, NULL, NULL, '1.	Deviasi RPD < 5% mencerminkan akurasi perencanaan kas dan stabilitas likuiditas wilayah;
2.	Nilai deviasi menunjukkan efektivitas koordinasi Satker–KPPN–Kanwil;
3.	Satker dengan deviasi tinggi perlu menjadi prioritas pembinaan.', 1, NULL);


INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (155, 'Helpdesk - Asistensi', 'Pelaksanaan kegiatan asistensi oleh KPPN kepada satker dalam rangka peningkatan kualitas pelaksanaan anggaran, tata kelola keuangan, serta digitalisasi layanan perbendaharaan.', 7, 40, 22, 0, 'Helpdesk - Asistensi', NULL, NULL, NULL, '-Laporan pelaksanaan kegiatan; dan/atau
-Bukti keterlibatan kegiatan FGD/
Sharing Session (misalnya ST/ Undangan, Daftar Hadir)''', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Nota Dinas Sekretaris DJPb Nomor ND-2168/PB.1/2025 hal Standar-disasi Kegiatan Manajemen Instansi Vertikal DJPb.', NULL, NULL, NULL, '1. Asistensi merupakan bentuk pembinaan langsung dan responsif KPPN kepada satker atas permasalahan teknis dan substantif pelaksanaan anggaran.
2. Kegiatan ini bertujuan meningkatkan kualitas tata kelola keuangan dan literasi digital perbendaharaan.
3. Asistensi menjadi indikator efektivitas peran KPPN sebagai financial advisor dan katalis peningkatan kinerja satker.', 6, 'a');

INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (156, 'Helpdesk - Responsivitas Penyelesaian Permalasahan melalui HAI CSO', 'Berdasarkan Laporan HAI CSO dari aplikasi My intress', 7, 40, 22, 0, 'Helpdesk - Responsivitas Penyelesaian Permalasahan melalui HAI CSO', NULL, NULL, NULL, 'Laporan HAI CSO pada My Intress', '1. Perdirjen Perbendaharaan Nomor PER-8/PB/2020 tentang Pedoman Penyelenggaraan Layanan Help, Answer, Improve DJPb.
2. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.', NULL, NULL, NULL, '1. Kecepatan dan ketepatan jawaban merupakan indikator responsivitas dan kualitas pembinaan KPPN terhadap satker.
2. Kinerja responsivitas HAI CSO mencerminkan profesionalisme dan kepuasan pengguna layanan perbendaharaan.', 6, 'b');

INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (166, 'Pelaksanaan Monev terkait Special Mission -Pengelolaan Keuangan BLU', 'Berdasarkan analisis permasalahan penyaluran pengelolaan keuangan BLU, KPPN melakukan monev baik secara langsung atau daring kepada BLU (dapat berkolaborasi dengan Kanwil DJPb) dengan ketentuan:', 7, 42, 27, 0, 'Pelaksanaan Monev terkait Special Mission -Pengelolaan Keuangan BLU', NULL, NULL, NULL, 'Laporan/bukti dukung kegiatan monev kepada BLU', '1. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
2. Nota Dinas Sekretaris DJPb Nomor ND-2168/PB.1/2025 hal Standar-disasi Kegiatan Manajemen Instansi Vertikal DJPb.', NULL, NULL, NULL, '1. Monev dilakukan dengan pendekatan analisis berbasis data laporan keuangan BLU, RBA, dan realisasi kas pada sistem DJPb.
2. Fokus pembinaan diarahkan untuk memastikan kepatuhan terhadap ketentuan pengelolaan keuangan BLU.
3. Hasil monev digunakan untuk memberikan rekomendasi perbaikan pengelolaan keuangan BLU serta mendorong peningkatan kualitas layanan publik oleh BLU', 16, 'a');
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (167, 'Pelaksanaan Monev terkait Special Mission -Pelaksanaan Monev Pembiayaan Umi', 'Kegiatan monev yang dilaksanakan oleh KPPN dapat meliputi namun tidak terbatas pada kegiatan publikasi ke Masyarakat (FGD, pekan bazar UMKM, postingan di medsos), identifikasi oleh LKBB potensial Kerjasama dengan Pemda dsb.', 7, 42, 27, 0, 'Pelaksanaan Monev terkait Special Mission -Pengelolaan Keuangan BLU', NULL, NULL, NULL, 'Laporan/bukti dukung kegiatan monev kepada BLU', '1. Kepdirjen Perbendaharaan Nomor KEP-112/PB/2023 tentang Petunjuk Teknis Pemberdayaan UMKM Lingkup DJPb.
2. Kepdirjen Perbendaharaan Nomor KEP-32/PB/2024 tentang Program Penguatan Peran Kantor Pelayanan Perbendaharaan Negara Selaku Financial Advisory.
3. Nota Dinas Sekretaris DJPb Nomor ND-2168/PB.1/2025 hal Standar-disasi Kegiatan Manajemen Instansi Vertikal DJPb,', NULL, NULL, NULL, '1. Menunjukkan pembinaan aktif dan berkelanjutan.
2. Pelaksanaan monev mendukung peningkatan literasi keuangan dan inklusi pembiayaan ultra mikro bagi pelaku usaha kecil di daerah.', 16, 'b');
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (168, 'Pelaksanaan Monev terkait Special Mission -Pengumpulan Laporan Keuangan BUMD', 'KPPN cq Seksi Bank melakukan permintaan Laporan Keuangan BUMD Tahunan kepada Pemda sesuai hasil identifikasi yang dilakukan Kanwil DJPb', 7, 42, 27, 0, 'Pelaksanaan Monev terkait Special Mission -Pengelolaan Keuangan BLU', NULL, NULL, NULL, 'Laporan Keuangan BUMD periode tahunan yang berhasil diperoleh berdasarkan hasil identifikasi oleh Kanwil DJPb', 'Perdirjen Perbendaharaan Nomor PER-10/PB/2024 tentang Petunjuk Teknis Penyusunan Laporan Statistik Keuangan Pemerintah sektor Korporasi Publik.', NULL, NULL, NULL, '1. Laporan keuangan BUMD yang diperoleh menjadi data sumber bagi translasi kertas kerja penyusunan Laporan Statistik Keuangan Pemerintah sektor Korporasi Publik (LSKP-KP) periode tahunan tingkat nasional.
2. Kolaborasi dan sinergi KPPN dengan Kanwil DJPb mendukung kelancaran pengumpulan laporan keuangan BUMD serta penyelesaian translasi dan unggah secara tepat waktu dan berkualitas.', 16, 'c');
INSERT INTO public.checklist_ref (id, title, header, komponen_id, subkomponen_id, subsubkomponen_id, standardisasi, matrix_title, file1, file2, instruksi, contoh_file, peraturan, uic, standardisasi_id, deleted, critical_point, urut, urut_huruf) VALUES (169, 'Pelaksanaan Monev terkait Special Mission -Penyelesaian Translasi dan Unggah Laporan Keuangan BUMD', 'Berdasarkan laporan keuangan BUMD yang diperoleh, KPPN melakukan translasi ke dalam kertas kerja korporasi publik.', 7, 42, 27, 0, 'Pelaksanaan Monev terkait Special Mission -Pengelolaan Keuangan BLU', NULL, NULL, NULL, 'Kertas kerja translasi data laporan keuangan BUMD yang telah terisi dan diunggah pada sistem informasi', 'Perdirjen Nomor PER-10/PB/2024 tentang Petunjuk Teknis Penyusunan Laporan Statistik Keuangan Pemerintah sektor Korporasi Publik.', NULL, NULL, NULL, '1. Translasi dari laporan keuangan BUMD ke dalam kertas kerja merupakan proses mapping dari akun pada laporan keuangan ke dalam akun statistik keuangan pemerintah/GFS.
2. Hasil translasi kemudian dikompilasi secara nasional dalam rangka penyusunan LSKP-KP.', 16, 'd');




